#include <algorithm>
#include <atomic>
#include <chrono>
#include <cmath>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <fstream>
#include <iostream>
#include <mutex>
#include <numeric>
#include <random>
#include <thread>
#include <vector>

struct Vec3f {
    float x, y, z;
};

struct Vec3d {
    double x, y, z;
    Vec3d operator+(const Vec3d& o) const { return {x + o.x, y + o.y, z + o.z}; }
    Vec3d operator-(const Vec3d& o) const { return {x - o.x, y - o.y, z - o.z}; }
    Vec3d operator*(double s) const { return {x * s, y * s, z * s}; }
    double dot(const Vec3d& o) const { return x * o.x + y * o.y + z * o.z; }
    Vec3d cross(const Vec3d& o) const {
        return {y * o.z - z * o.y, z * o.x - x * o.z, x * o.y - y * o.x};
    }
    double norm() const { return std::sqrt(x * x + y * y + z * z); }
};

struct Quat {
    double w, x, y, z;
    void normalize() {
        double n = std::sqrt(w * w + x * x + y * y + z * z);
        if (n > 0) { w /= n; x /= n; y /= n; z /= n; }
        if (w < 0) { w = -w; x = -x; y = -y; z = -z; }
    }
    Quat conj() const { return {w, -x, -y, -z}; }
    Quat operator*(const Quat& o) const {
        return {
            w * o.w - x * o.x - y * o.y - z * o.z,
            w * o.x + x * o.w + y * o.z - z * o.y,
            w * o.y - x * o.z + y * o.w + z * o.x,
            w * o.z + x * o.y - y * o.x + z * o.w
        };
    }
};

static inline Quat quat_from_rotvec(const Vec3d& rv) {
    double angle = rv.norm();
    if (angle < 1e-12) return {1.0, 0.5 * rv.x, 0.5 * rv.y, 0.5 * rv.z};
    double s = std::sin(0.5 * angle) / angle;
    Quat q{std::cos(0.5 * angle), rv.x * s, rv.y * s, rv.z * s};
    q.normalize();
    return q;
}

static inline Vec3d rotvec_from_quat(Quat q) {
    if (q.w < 0) { q.w = -q.w; q.x = -q.x; q.y = -q.y; q.z = -q.z; }
    double vnorm = std::sqrt(q.x * q.x + q.y * q.y + q.z * q.z);
    if (vnorm < 1e-12) return {2.0 * q.x, 2.0 * q.y, 2.0 * q.z};
    double angle = 2.0 * std::atan2(vnorm, q.w);
    double scale = angle / vnorm;
    return {q.x * scale, q.y * scale, q.z * scale};
}

static inline double quat_angle_dist(const Quat& a, const Quat& b) {
    double d = std::abs(a.w * b.w + a.x * b.x + a.y * b.y + a.z * b.z);
    if (d >= 1.0) return 0.0;
    return 2.0 * std::acos(d);
}

static inline Quat quat_slerp(const Quat& a, Quat b, double t) {
    double dot = a.w * b.w + a.x * b.x + a.y * b.y + a.z * b.z;
    if (dot < 0.0) {
        dot = -dot;
        b = {-b.w, -b.x, -b.y, -b.z};
    }
    if (dot > 0.9995) {
        Quat r{a.w + t * (b.w - a.w), a.x + t * (b.x - a.x),
               a.y + t * (b.y - a.y), a.z + t * (b.z - a.z)};
        r.normalize();
        return r;
    }
    double theta_0 = std::acos(dot);
    double theta = theta_0 * t;
    double sin_theta = std::sin(theta);
    double sin_theta_0 = std::sin(theta_0);
    double s0 = std::cos(theta) - dot * sin_theta / sin_theta_0;
    double s1 = sin_theta / sin_theta_0;
    Quat r{s0 * a.w + s1 * b.w, s0 * a.x + s1 * b.x,
           s0 * a.y + s1 * b.y, s0 * a.z + s1 * b.z};
    r.normalize();
    return r;
}

struct Pose {
    Vec3d p;
    Quat q;
};

struct Mat3f {
    float m[9];
    float tx, ty, tz;
    static Mat3f from_pose(const Pose& pose) {
        Mat3f res;
        double w = pose.q.w, x = pose.q.x, y = pose.q.y, z = pose.q.z;
        double xx = x * x, yy = y * y, zz = z * z;
        double xy = x * y, xz = x * z, yz = y * z;
        double wx = w * x, wy = w * y, wz = w * z;
        res.m[0] = (float)(1.0 - 2.0 * (yy + zz));
        res.m[1] = (float)(2.0 * (xy - wz));
        res.m[2] = (float)(2.0 * (xz + wy));
        res.m[3] = (float)(2.0 * (xy + wz));
        res.m[4] = (float)(1.0 - 2.0 * (xx + zz));
        res.m[5] = (float)(2.0 * (yz - wx));
        res.m[6] = (float)(2.0 * (xz - wy));
        res.m[7] = (float)(2.0 * (yz + wx));
        res.m[8] = (float)(1.0 - 2.0 * (xx + yy));
        res.tx = (float)pose.p.x;
        res.ty = (float)pose.p.y;
        res.tz = (float)pose.p.z;
        return res;
    }
    inline Vec3f apply(const Vec3f& v) const {
        return {
            m[0] * v.x + m[1] * v.y + m[2] * v.z + tx,
            m[3] * v.x + m[4] * v.y + m[5] * v.z + ty,
            m[6] * v.x + m[7] * v.y + m[8] * v.z + tz
        };
    }
    inline Vec3f rotate_only(const Vec3f& v) const {
        return {
            m[0] * v.x + m[1] * v.y + m[2] * v.z,
            m[3] * v.x + m[4] * v.y + m[5] * v.z,
            m[6] * v.x + m[7] * v.y + m[8] * v.z
        };
    }
};

struct BVHNode {
    Vec3f center;
    float radius;
    int left;   // -1 if leaf
    int right;
    int start;
    int count;
};

struct WorldModel {
    int nx, ny, nz;
    float dx, inv_dx;
    float gmin_x, gmin_y, gmin_z;
    float gmax_x, gmax_y, gmax_z;
    float bmin_x, bmin_y, bmin_z;
    float bmax_x, bmax_y, bmax_z;
    Vec3d pos_b0;

    std::vector<int16_t> sdf_i16;
    std::vector<Vec3f> med_c;
    std::vector<float> med_r;
    std::vector<Vec3f> b_coarse;
    std::vector<Vec3f> b_med;
    std::vector<Vec3f> b_fine;
    Vec3f b_local_min, b_local_max;
    float max_local_radius;

    std::vector<BVHNode> bvh;

    void load(const char* path) {
        FILE* f = std::fopen(path, "rb");
        if (!f) { std::perror("fopen"); std::exit(1); }
        int32_t shape[3];
        double d_dx, gmin[3], bmin[3], bmax[3], pb0[3];
        int32_t counts[4];
        if (std::fread(shape, sizeof(int32_t), 3, f) != 3) std::exit(1);
        if (std::fread(&d_dx, sizeof(double), 1, f) != 1) std::exit(1);
        if (std::fread(gmin, sizeof(double), 3, f) != 3) std::exit(1);
        if (std::fread(bmin, sizeof(double), 3, f) != 3) std::exit(1);
        if (std::fread(bmax, sizeof(double), 3, f) != 3) std::exit(1);
        if (std::fread(pb0, sizeof(double), 3, f) != 3) std::exit(1);
        if (std::fread(counts, sizeof(int32_t), 4, f) != 4) std::exit(1);

        nx = shape[0]; ny = shape[1]; nz = shape[2];
        dx = (float)d_dx; inv_dx = 1.0f / dx;
        gmin_x = (float)gmin[0]; gmin_y = (float)gmin[1]; gmin_z = (float)gmin[2];
        gmax_x = gmin_x + (nx - 1.001f) * dx;
        gmax_y = gmin_y + (ny - 1.001f) * dx;
        gmax_z = gmin_z + (nz - 1.001f) * dx;
        bmin_x = (float)bmin[0]; bmin_y = (float)bmin[1]; bmin_z = (float)bmin[2];
        bmax_x = (float)bmax[0]; bmax_y = (float)bmax[1]; bmax_z = (float)bmax[2];
        pos_b0 = {pb0[0], pb0[1], pb0[2]};

        med_c.resize(counts[0]);
        med_r.resize(counts[0]);
        b_coarse.resize(counts[1]);
        b_med.resize(counts[2]);
        b_fine.resize(counts[3]);

        if (std::fread(med_c.data(), sizeof(Vec3f), counts[0], f) != (size_t)counts[0]) std::exit(1);
        if (std::fread(med_r.data(), sizeof(float), counts[0], f) != (size_t)counts[0]) std::exit(1);
        if (std::fread(b_coarse.data(), sizeof(Vec3f), counts[1], f) != (size_t)counts[1]) std::exit(1);
        if (std::fread(b_med.data(), sizeof(Vec3f), counts[2], f) != (size_t)counts[2]) std::exit(1);
        if (std::fread(b_fine.data(), sizeof(Vec3f), counts[3], f) != (size_t)counts[3]) std::exit(1);

        size_t total_vox = (size_t)nx * ny * nz;
        sdf_i16.resize(total_vox);
        if (std::fread(sdf_i16.data(), sizeof(int16_t), total_vox, f) != total_vox) std::exit(1);
        std::fclose(f);

        max_local_radius = 0.0f;
        b_local_min = {1e9f, 1e9f, 1e9f};
        b_local_max = {-1e9f, -1e9f, -1e9f};
        for (const auto& p : b_fine) {
            float r = std::sqrt(p.x * p.x + p.y * p.y + p.z * p.z);
            if (r > max_local_radius) max_local_radius = r;
            b_local_min.x = std::min(b_local_min.x, p.x);
            b_local_min.y = std::min(b_local_min.y, p.y);
            b_local_min.z = std::min(b_local_min.z, p.z);
            b_local_max.x = std::max(b_local_max.x, p.x);
            b_local_max.y = std::max(b_local_max.y, p.y);
            b_local_max.z = std::max(b_local_max.z, p.z);
        }

        bvh.reserve(b_fine.size() / 16);
        build_bvh(0, (int)b_fine.size());
        std::printf("Loaded WorldModel: grid=(%d,%d,%d), fine=%zu, bvh_nodes=%zu, max_r=%.3fm\n",
                    nx, ny, nz, b_fine.size(), bvh.size(), max_local_radius);
    }

    int build_bvh(int start, int count) {
        int node_idx = (int)bvh.size();
        bvh.push_back({});
        Vec3f mn{1e9f, 1e9f, 1e9f}, mx{-1e9f, -1e9f, -1e9f};
        for (int i = start; i < start + count; ++i) {
            const auto& p = b_fine[i];
            if (p.x < mn.x) mn.x = p.x;
            if (p.y < mn.y) mn.y = p.y;
            if (p.z < mn.z) mn.z = p.z;
            if (p.x > mx.x) mx.x = p.x;
            if (p.y > mx.y) mx.y = p.y;
            if (p.z > mx.z) mx.z = p.z;
        }
        Vec3f center{0.5f * (mn.x + mx.x), 0.5f * (mn.y + mx.y), 0.5f * (mn.z + mx.z)};
        float r2 = 0.0f;
        for (int i = start; i < start + count; ++i) {
            float dx_ = b_fine[i].x - center.x;
            float dy_ = b_fine[i].y - center.y;
            float dz_ = b_fine[i].z - center.z;
            float d2 = dx_ * dx_ + dy_ * dy_ + dz_ * dz_;
            if (d2 > r2) r2 = d2;
        }
        bvh[node_idx].center = center;
        bvh[node_idx].radius = std::sqrt(r2);
        bvh[node_idx].start = start;
        bvh[node_idx].count = count;

        if (count <= 48) {
            bvh[node_idx].left = -1;
            bvh[node_idx].right = -1;
            return node_idx;
        }

        float sx = mx.x - mn.x, sy = mx.y - mn.y, sz = mx.z - mn.z;
        int axis = (sx >= sy && sx >= sz) ? 0 : ((sy >= sz) ? 1 : 2);
        int mid = start + count / 2;
        std::nth_element(b_fine.begin() + start, b_fine.begin() + mid, b_fine.begin() + start + count,
                         [axis](const Vec3f& a, const Vec3f& b) {
                             return (axis == 0) ? (a.x < b.x) : ((axis == 1) ? (a.y < b.y) : (a.z < b.z));
                         });
        int left = build_bvh(start, mid - start);
        int right = build_bvh(mid, start + count - mid);
        bvh[node_idx].left = left;
        bvh[node_idx].right = right;
        return node_idx;
    }

    inline float query_sdf(const Vec3f& w) const {
        if (w.x <= gmin_x || w.x >= gmax_x ||
            w.y <= gmin_y || w.y >= gmax_y ||
            w.z <= gmin_z || w.z >= gmax_z) {
            float dx_ = std::max(0.0f, std::max(bmin_x - w.x, w.x - bmax_x));
            float dy_ = std::max(0.0f, std::max(bmin_y - w.y, w.y - bmax_y));
            float dz_ = std::max(0.0f, std::max(bmin_z - w.z, w.z - bmax_z));
            return std::sqrt(dx_ * dx_ + dy_ * dy_ + dz_ * dz_);
        }
        float fx = (w.x - gmin_x) * inv_dx;
        float fy = (w.y - gmin_y) * inv_dx;
        float fz = (w.z - gmin_z) * inv_dx;
        int i = (int)fx;
        int j = (int)fy;
        int k = (int)fz;
        float tx = fx - i;
        float ty = fy - j;
        float tz = fz - k;

        size_t s_y = (size_t)nz;
        size_t s_x = (size_t)ny * nz;
        size_t base = (size_t)i * s_x + (size_t)j * s_y + (size_t)k;

        float c000 = sdf_i16[base];
        float c001 = sdf_i16[base + 1];
        float c010 = sdf_i16[base + s_y];
        float c011 = sdf_i16[base + s_y + 1];
        float c100 = sdf_i16[base + s_x];
        float c101 = sdf_i16[base + s_x + 1];
        float c110 = sdf_i16[base + s_x + s_y];
        float c111 = sdf_i16[base + s_x + s_y + 1];

        float c00 = c000 + tx * (c100 - c000);
        float c01 = c001 + tx * (c101 - c001);
        float c10 = c010 + tx * (c110 - c010);
        float c11 = c011 + tx * (c111 - c011);
        float c0 = c00 + ty * (c10 - c00);
        float c1 = c01 + ty * (c11 - c01);
        return (c0 + tz * (c1 - c0)) * 0.0001f;
    }

    inline Vec3f query_sdf_grad(const Vec3f& w) const {
        const float eps = 0.005f;
        float gx = query_sdf({w.x + eps, w.y, w.z}) - query_sdf({w.x - eps, w.y, w.z});
        float gy = query_sdf({w.x, w.y + eps, w.z}) - query_sdf({w.x, w.y - eps, w.z});
        float gz = query_sdf({w.x, w.y, w.z + eps}) - query_sdf({w.x, w.y, w.z - eps});
        float n = std::sqrt(gx * gx + gy * gy + gz * gz);
        if (n < 1e-8f) return {0.0f, 0.0f, 1.0f};
        return {gx / n, gy / n, gz / n};
    }

    // Exact clearance over all 224,910 fine surface points using BVH + medial early reject!
    // Stops early as soon as clearance < stop_below.
    float clearance_exact(const Pose& pose, float stop_below, float max_cap = 0.50f, int* closest_fine_idx = nullptr) const {
        if (pose.p.x < -0.75 || pose.p.x > 3.15 ||
            pose.p.y < -0.75 || pose.p.y > 3.15 ||
            pose.p.z < -0.75 || pose.p.z > 3.15) {
            return -1.0f;
        }
        Mat3f T = Mat3f::from_pose(pose);

        // Quick bounding sphere check around tube_b
        float d_root = query_sdf(T.apply(bvh[0].center)) - bvh[0].radius - 0.002f;
        if (d_root >= max_cap) return d_root;

        // Stage 0: 159 medial interior spheres for ultra-fast collision reject
        for (size_t i = 0; i < med_c.size(); ++i) {
            float d = query_sdf(T.apply(med_c[i])) - (med_r[i] - 0.002f);
            if (d < stop_below) return d;
        }

        // Stage 1: BVH branch-and-bound
        float best = max_cap;
        int best_idx = 0;
        int stack[64];
        float stack_lb[64];
        int sp = 0;

        stack[sp] = 0;
        stack_lb[sp] = d_root;
        sp++;

        while (sp > 0) {
            --sp;
            if (stack_lb[sp] >= best) continue;
            int u = stack[sp];
            const BVHNode& node = bvh[u];
            if (node.left < 0) {
                int end = node.start + node.count;
                for (int i = node.start; i < end; ++i) {
                    float d = query_sdf(T.apply(b_fine[i]));
                    if (d < best) {
                        best = d;
                        best_idx = i;
                        if (best < stop_below) {
                            if (closest_fine_idx) *closest_fine_idx = best_idx;
                            return best;
                        }
                    }
                }
            } else {
                const BVHNode& L = bvh[node.left];
                const BVHNode& R = bvh[node.right];
                float lbL = query_sdf(T.apply(L.center)) - L.radius - 0.0018f;
                float lbR = query_sdf(T.apply(R.center)) - R.radius - 0.0018f;
                // Push larger lb first so smaller lb is popped first!
                if (lbL < lbR) {
                    if (lbR < best) { stack[sp] = node.right; stack_lb[sp++] = lbR; }
                    if (lbL < best) { stack[sp] = node.left;  stack_lb[sp++] = lbL; }
                } else {
                    if (lbL < best) { stack[sp] = node.left;  stack_lb[sp++] = lbL; }
                    if (lbR < best) { stack[sp] = node.right; stack_lb[sp++] = lbR; }
                }
            }
        }
        if (closest_fine_idx) *closest_fine_idx = best_idx;
        return best;
    }

    // Coarse clearance on 8032 points + gradient push for sample retraction!
    bool retract_pose(Pose& pose, float target_clear, int max_iters = 10) const {
        for (int it = 0; it < max_iters; ++it) {
            if (pose.p.x < -0.72 || pose.p.x > 3.12 ||
                pose.p.y < -0.72 || pose.p.y > 3.12 ||
                pose.p.z < -0.72 || pose.p.z > 3.12) return false;

            Mat3f T = Mat3f::from_pose(pose);
            float min_d = 1e9f;
            Vec3d f_sum{0, 0, 0}, tau_sum{0, 0, 0};
            int n_active = 0;
            // Check coarse surface points
            for (size_t i = 0; i < b_coarse.size(); i += 2) {
                Vec3f w = T.apply(b_coarse[i]);
                float d = query_sdf(w);
                if (d < min_d) min_d = d;
                if (d < target_clear + 0.015f) {
                    Vec3f g = query_sdf_grad(w);
                    Vec3f r = T.rotate_only(b_coarse[i]);
                    double wgt = (target_clear + 0.020 - d);
                    Vec3d gd{g.x, g.y, g.z};
                    Vec3d rd{r.x, r.y, r.z};
                    f_sum = f_sum + gd * wgt;
                    tau_sum = tau_sum + rd.cross(gd) * wgt;
                    n_active++;
                }
            }
            if (min_d >= target_clear) {
                // Confirm with exact BVH!
                float ex = clearance_exact(pose, target_clear);
                if (ex >= target_clear) return true;
                // Push out exact closest point
                int idx = 0;
                ex = clearance_exact(pose, -10.0f, 0.20f, &idx);
                Vec3f w = T.apply(b_fine[idx]);
                Vec3f g = query_sdf_grad(w);
                Vec3f r = T.rotate_only(b_fine[idx]);
                double push = (target_clear - ex) + 0.004;
                pose.p = pose.p + Vec3d{g.x, g.y, g.z} * push;
                Vec3d tau = Vec3d{r.x, r.y, r.z}.cross(Vec3d{g.x, g.y, g.z});
                if (tau.norm() > 1e-6) {
                    pose.q = quat_from_rotvec(tau * (0.3 * push / std::max(0.2, tau.norm()))) * pose.q;
                    pose.q.normalize();
                }
                continue;
            }
            if (min_d < -0.06f || n_active == 0) return false;
            double fn = f_sum.norm();
            double tn = tau_sum.norm();
            double need = (target_clear - min_d) + 0.005;
            if (fn > 1e-8) {
                pose.p = pose.p + f_sum * (std::min(0.025, need) / fn);
            }
            if (tn > 1e-8) {
                pose.q = quat_from_rotvec(tau_sum * (std::min(0.035, 0.8 * need) / tn)) * pose.q;
                pose.q.normalize();
            }
        }
        return clearance_exact(pose, target_clear) >= target_clear;
    }

    // Check if pose can slide to infinity along SOME straight line direction with clearance >= min_ray_clear!
    bool check_ray_escape(const Pose& pose, float min_ray_clear, Vec3d* best_dir = nullptr, float* best_ray_clear = nullptr) const {
        // Generate 160 Fibonacci directions + 6 cardinal directions
        static std::vector<Vec3d> dirs;
        static std::once_flag flag;
        std::call_once(flag, []() {
            dirs.push_back({0, 0, 1});
            dirs.push_back({0, 0, -1});
            dirs.push_back({1, 0, 0});
            dirs.push_back({-1, 0, 0});
            dirs.push_back({0, 1, 0});
            dirs.push_back({0, -1, 0});
            const int N = 160;
            const double phi = M_PI * (3.0 - std::sqrt(5.0));
            for (int i = 0; i < N; ++i) {
                double y = 1.0 - (i / (double)(N - 1)) * 2.0;
                double radius = std::sqrt(std::max(0.0, 1.0 - y * y));
                double theta = phi * i;
                dirs.push_back({std::cos(theta) * radius, y, std::sin(theta) * radius});
            }
        });

        float c0 = clearance_exact(pose, min_ray_clear);
        if (c0 < min_ray_clear) return false;

        float best_c = -1.0f;
        Vec3d best_u{0, 0, 1};

        for (const auto& u : dirs) {
            float ray_min = c0;
            double tau = 0.0;
            bool ok = true;
            // Max translation needed before bounding spheres separate completely (~4.5m)
            while (tau < 4.5) {
                double step = std::max(0.015, 0.85 * (double)ray_min);
                tau += step;
                // Note: along ray escape to infinity, ignore workspace clamp box!
                Pose pt{pose.p + u * tau, pose.q};
                Mat3f T = Mat3f::from_pose(pt);
                float d_root = query_sdf(T.apply(bvh[0].center)) - bvh[0].radius - 0.002f;
                if (d_root > 0.30f && tau > 2.5) break; // escaped!
                // Evaluate BVH without workspace box check
                float c = max_ray_bvh_clearance(T, min_ray_clear);
                if (c < min_ray_clear) { ok = false; break; }
                if (c < ray_min) ray_min = c;
            }
            if (ok) {
                if (!best_dir) return true;
                if (ray_min > best_c) {
                    best_c = ray_min;
                    best_u = u;
                }
            }
        }
        if (best_c >= min_ray_clear) {
            if (best_dir) *best_dir = best_u;
            if (best_ray_clear) *best_ray_clear = best_c;
            return true;
        }
        return false;
    }

    float max_ray_bvh_clearance(const Mat3f& T, float stop_below) const {
        float d_root = query_sdf(T.apply(bvh[0].center)) - bvh[0].radius - 0.002f;
        if (d_root >= 0.35f) return d_root;
        for (size_t i = 0; i < med_c.size(); ++i) {
            float d = query_sdf(T.apply(med_c[i])) - (med_r[i] - 0.002f);
            if (d < stop_below) return d;
        }
        float best = 0.35f;
        int stack[64];
        float stack_lb[64];
        int sp = 0;
        stack[sp] = 0; stack_lb[sp++] = d_root;
        while (sp > 0) {
            --sp;
            if (stack_lb[sp] >= best) continue;
            const BVHNode& node = bvh[stack[sp]];
            if (node.left < 0) {
                int end = node.start + node.count;
                for (int i = node.start; i < end; ++i) {
                    float d = query_sdf(T.apply(b_fine[i]));
                    if (d < best) {
                        best = d;
                        if (best < stop_below) return best;
                    }
                }
            } else {
                const BVHNode& L = bvh[node.left];
                const BVHNode& R = bvh[node.right];
                float lbL = query_sdf(T.apply(L.center)) - L.radius - 0.0018f;
                float lbR = query_sdf(T.apply(R.center)) - R.radius - 0.0018f;
                if (lbL < lbR) {
                    if (lbR < best) { stack[sp] = node.right; stack_lb[sp++] = lbR; }
                    if (lbL < best) { stack[sp] = node.left;  stack_lb[sp++] = lbL; }
                } else {
                    if (lbL < best) { stack[sp] = node.left;  stack_lb[sp++] = lbL; }
                    if (lbR < best) { stack[sp] = node.right; stack_lb[sp++] = lbR; }
                }
            }
        }
        return best;
    }

    // Check continuous edge under BOTH synchronized interpolation AND independent speed-limited interpolation!
    bool edge_valid(const Pose& a, const Pose& b, float min_clear, bool check_both_laws = false, float* min_edge_clear = nullptr) const {
        double dp = (b.p - a.p).norm();
        double da = quat_angle_dist(a.q, b.q);
        double tip_travel = dp + max_local_radius * da;
        int n_steps = std::max(2, (int)std::ceil(tip_travel / 0.004)); // every 4mm of tip travel!
        float worst = 1e9f;
        for (int i = 1; i <= n_steps; ++i) {
            double s = (double)i / n_steps;
            Pose mid{a.p + (b.p - a.p) * s, quat_slerp(a.q, b.q, s)};
            float c = clearance_exact(mid, min_clear);
            if (c < min_clear) return false;
            if (c < worst) worst = c;
        }
        if (check_both_laws && dp > 1e-6 && da > 1e-6) {
            // Independent speed law: v_lin = 0.1 m/s, v_ang = 0.1 rad/s
            double T_lin = dp / 0.1;
            double T_ang = da / 0.1;
            double T_tot = std::max(T_lin, T_ang);
            for (int i = 1; i < n_steps; ++i) {
                double t = (T_tot * i) / n_steps;
                double s_lin = std::min(1.0, t / T_lin);
                double s_ang = std::min(1.0, t / T_ang);
                Pose mid{a.p + (b.p - a.p) * s_lin, quat_slerp(a.q, b.q, s_ang)};
                float c = clearance_exact(mid, min_clear);
                if (c < min_clear) return false;
                if (c < worst) worst = c;
            }
        }
        if (min_edge_clear) *min_edge_clear = worst;
        return true;
    }
};

static inline double pose_dist(const Pose& a, const Pose& b) {
    double dp = (a.p - b.p).norm();
    double da = quat_angle_dist(a.q, b.q);
    return dp + 0.8 * da;
}

static inline Pose pose_interp(const Pose& a, const Pose& b, double t) {
    return {a.p + (b.p - a.p) * t, quat_slerp(a.q, b.q, t)};
}

struct RRTNode {
    Pose pose;
    int parent;
};

int nearest_node(const std::vector<RRTNode>& tree, const Pose& q) {
    int best = 0;
    double best_d = 1e18;
    for (int i = 0; i < (int)tree.size(); ++i) {
        double d = pose_dist(tree[i].pose, q);
        if (d < best_d) { best_d = d; best = i; }
    }
    return best;
}

// Extend tree toward target; returns last added node index (-1 if none), sets reached=true if connected!
int extend_tree(const WorldModel& wm, std::vector<RRTNode>& tree, const Pose& target,
                float min_clear, double step_size, bool allow_slide, bool& reached, int max_steps = 80) {
    reached = false;
    int cur_idx = nearest_node(tree, target);
    int added_idx = -1;

    for (int step = 0; step < max_steps; ++step) {
        const Pose& cur = tree[cur_idx].pose;
        double d = pose_dist(cur, target);
        if (d < 1e-6) { reached = true; return cur_idx; }
        double t = std::min(1.0, step_size / d);
        Pose next = pose_interp(cur, target, t);

        if (wm.edge_valid(cur, next, min_clear)) {
            cur_idx = (int)tree.size();
            tree.push_back({next, (added_idx == -1) ? nearest_node(tree, cur) : added_idx});
            // Wait: fix parent carefully! `cur_idx` before push was the exact parent!
            tree.back().parent = cur_idx - 0; // wait, let's write parent cleanly below!
            added_idx = cur_idx;
            if (t >= 1.0 - 1e-9) { reached = true; return cur_idx; }
        } else if (allow_slide && step < 12) {
            // Try clearance retraction on `next` so tree slides along narrow curved channel!
            Pose slid = next;
            if (wm.retract_pose(slid, min_clear + 0.002f, 5) &&
                pose_dist(cur, slid) <= step_size * 1.8 &&
                pose_dist(slid, target) < d - 0.005 &&
                wm.edge_valid(cur, slid, min_clear)) {
                int p_idx = cur_idx;
                cur_idx = (int)tree.size();
                tree.push_back({slid, p_idx});
                added_idx = cur_idx;
            } else {
                break;
            }
        } else {
            break;
        }
    }
    return added_idx;
}

int main(int argc, char** argv) {
    float target_clear = (argc > 1) ? std::atof(argv[1]) : 0.008f;
    WorldModel wm;
    wm.load("/app/planner_data.bin");

    Pose q_start{wm.pos_b0, {1.0, 0.0, 0.0, 0.0}};
    int cidx = 0;
    float start_clear = wm.clearance_exact(q_start, -1.0f, 0.50f, &cidx);
    std::printf("Initial pose clearance: %.3f mm\n", start_clear * 1000.0f);

    // Benchmark 10,000 random clearance queries
    {
        std::mt19937 rng(123);
        std::uniform_real_distribution<double> up(-0.4, 2.5);
        std::normal_distribution<double> uq(0.0, 1.0);
        auto t0 = std::chrono::high_resolution_clock::now();
        int free_cnt = 0;
        for (int i = 0; i < 10000; ++i) {
            Quat q{uq(rng), uq(rng), uq(rng), uq(rng)};
            q.normalize();
            Pose p{{up(rng), up(rng), up(rng)}, q};
            if (wm.clearance_exact(p, target_clear) >= target_clear) free_cnt++;
        }
        auto t1 = std::chrono::high_resolution_clock::now();
        double ms = std::chrono::duration<double, std::milli>(t1 - t0).count();
        std::printf("10,000 exact BVH queries in %.2f ms (%.0f queries/sec/thread), free=%d\n",
                    ms, 10000.0 / (ms * 1e-3), free_cnt);
    }

    // Multi-threaded parallel BiRRT-Connect across 8 worker threads!
    std::atomic<bool> solved{false};
    std::mutex sol_mtx;
    std::vector<Pose> best_raw_path;

    int n_threads = 8;
    std::printf("Running %d-thread BiRRT-Connect with min_clear=%.2f mm...\n", n_threads, target_clear * 1000.0f);
    auto plan_t0 = std::chrono::high_resolution_clock::now();

    auto worker = [&](int tid) {
        std::mt19937 rng(1000 + tid * 977);
        std::uniform_real_distribution<double> uni01(0.0, 1.0);
        std::normal_distribution<double> gauss(0.0, 1.0);

        std::vector<RRTNode> treeA;
        std::vector<RRTNode> treeB;
        treeA.reserve(50000);
        treeB.reserve(50000);
        treeA.push_back({q_start, -1});

        // Seed treeB with several clearly separated, ray-escaping goal poses inside workspace!
        std::vector<Vec3d> goal_ps = {
            {1.2, 0.36, 1.35},
            {1.2, 1.80, 0.90},
            {-0.3, 0.36, 1.10},
            {2.3, 0.36, 1.20},
            {1.2, -0.40, 1.10},
        };
        Pose q_goal{goal_ps[tid % goal_ps.size()], {1.0, 0.0, 0.0, 0.0}};
        if (wm.clearance_exact(q_goal, 0.05f) < 0.05f || !wm.check_ray_escape(q_goal, 0.05f)) {
            q_goal = {{1.2, 0.36, 1.50}, {1.0, 0.0, 0.0, 0.0}};
        }
        treeB.push_back({q_goal, -1});

        const double step_size = 0.08;

        auto do_extend = [&](std::vector<RRTNode>& tree, const Pose& target, bool allow_slide, bool& reached, int max_st) -> int {
            reached = false;
            int cur_idx = nearest_node(tree, target);
            int added_idx = -1;
            for (int st = 0; st < max_st; ++st) {
                Pose cur = tree[cur_idx].pose;
                double d = pose_dist(cur, target);
                if (d < 1e-6) { reached = true; return cur_idx; }
                double t = std::min(1.0, step_size / d);
                Pose next = pose_interp(cur, target, t);
                if (wm.edge_valid(cur, next, target_clear)) {
                    int p_idx = cur_idx;
                    cur_idx = (int)tree.size();
                    tree.push_back({next, p_idx});
                    added_idx = cur_idx;
                    if (t >= 1.0 - 1e-9) { reached = true; return cur_idx; }
                } else if (allow_slide && st < 15) {
                    Pose slid = next;
                    if (wm.retract_pose(slid, target_clear + 0.002f, 6) &&
                        pose_dist(cur, slid) <= step_size * 1.8 &&
                        pose_dist(slid, target) < d - 0.004 &&
                        wm.edge_valid(cur, slid, target_clear)) {
                        int p_idx = cur_idx;
                        cur_idx = (int)tree.size();
                        tree.push_back({slid, p_idx});
                        added_idx = cur_idx;
                    } else {
                        break;
                    }
                } else {
                    break;
                }
            }
            return added_idx;
        };

        for (int iter = 0; iter < 200000 && !solved.load(std::memory_order_relaxed); ++iter) {
            Pose q_rand;
            double mode = uni01(rng);
            if (mode < 0.55) {
                // Focused narrow-passage box around tube_a + retraction!
                q_rand.p = {
                    -0.4 + uni01(rng) * 2.9,
                    -0.5 + uni01(rng) * 2.3,
                    -0.5 + uni01(rng) * 1.5
                };
                Quat q{gauss(rng), gauss(rng), gauss(rng), gauss(rng)};
                q.normalize();
                q_rand.q = q;
                float c = wm.clearance_exact(q_rand, target_clear);
                if (c < target_clear) {
                    if (c > -0.055f) {
                        if (!wm.retract_pose(q_rand, target_clear + 0.002f, 8)) continue;
                    } else {
                        continue;
                    }
                }
            } else if (mode < 0.80) {
                // Bridge / Gaussian perturbation around an existing forward-tree node!
                const Pose& base = treeA[rng() % treeA.size()].pose;
                double sigma_p = 0.25;
                double sigma_q = 0.45;
                q_rand.p = {base.p.x + gauss(rng) * sigma_p,
                            base.p.y + gauss(rng) * sigma_p,
                            base.p.z + gauss(rng) * sigma_p};
                Vec3d rv{gauss(rng) * sigma_q, gauss(rng) * sigma_q, gauss(rng) * sigma_q};
                q_rand.q = quat_from_rotvec(rv) * base.q;
                q_rand.q.normalize();
                if (!wm.retract_pose(q_rand, target_clear + 0.002f, 6)) continue;
            } else {
                // Wide workspace exploration
                q_rand.p = {
                    -0.65 + uni01(rng) * 3.70,
                    -0.65 + uni01(rng) * 3.70,
                    -0.65 + uni01(rng) * 2.60
                };
                Quat q{gauss(rng), gauss(rng), gauss(rng), gauss(rng)};
                q.normalize();
                q_rand.q = q;
                if (wm.clearance_exact(q_rand, target_clear) < target_clear) continue;
            }

            // Alternate trees, keeping track of which is A (start) vs B (goal)
            bool swap_trees = (treeA.size() > treeB.size());
            auto& t1 = swap_trees ? treeB : treeA;
            auto& t2 = swap_trees ? treeA : treeB;

            bool r1 = false;
            int idx1 = do_extend(t1, q_rand, true, r1, 25);
            if (idx1 >= 0) {
                // If we just extended treeA (start tree), check if the new node ALREADY ray-escapes!
                if (!swap_trees) {
                    const Pose& np = t1[idx1].pose;
                    if ((np.p - q_start.p).norm() > 0.65 && wm.clearance_exact(np, 0.030f) >= 0.030f) {
                        if (wm.check_ray_escape(np, 0.030f)) {
                            if (!solved.exchange(true)) {
                                std::lock_guard<std::mutex> lk(sol_mtx);
                                std::vector<Pose> path;
                                for (int cur = idx1; cur != -1; cur = t1[cur].parent) path.push_back(t1[cur].pose);
                                std::reverse(path.begin(), path.end());
                                best_raw_path = path;
                                std::printf("[Thread %d] Direct ray-escape found at iter %d! treeA=%zu, path_len=%zu\n",
                                            tid, iter, treeA.size(), path.size());
                            }
                            return;
                        }
                    }
                }

                bool r2 = false;
                int idx2 = do_extend(t2, t1[idx1].pose, true, r2, 80);
                if (r2 && idx2 >= 0) {
                    if (!solved.exchange(true)) {
                        std::lock_guard<std::mutex> lk(sol_mtx);
                        int iA = swap_trees ? idx2 : idx1;
                        int iB = swap_trees ? idx1 : idx2;
                        std::vector<Pose> pathA, pathB;
                        for (int cur = iA; cur != -1; cur = treeA[cur].parent) pathA.push_back(treeA[cur].pose);
                        std::reverse(pathA.begin(), pathA.end());
                        for (int cur = treeB[iB].parent; cur != -1; cur = treeB[cur].parent) pathB.push_back(treeB[cur].pose);
                        pathA.insert(pathA.end(), pathB.begin(), pathB.end());
                        best_raw_path = pathA;
                        std::printf("[Thread %d] Connected trees at iter %d! treeA=%zu, treeB=%zu, path_len=%zu\n",
                                    tid, iter, treeA.size(), treeB.size(), pathA.size());
                    }
                    return;
                }
            }
            if (tid == 0 && iter > 0 && iter % 2000 == 0) {
                std::printf("[Thread 0] iter=%d, treeA=%zu, treeB=%zu\n", iter, treeA.size(), treeB.size());
                std::fflush(stdout);
            }
        }
    };

    std::vector<std::thread> threads;
    for (int t = 0; t < n_threads; ++t) threads.emplace_back(worker, t);
    for (auto& th : threads) th.join();

    auto plan_t1 = std::chrono::high_resolution_clock::now();
    double plan_sec = std::chrono::duration<double>(plan_t1 - plan_t0).count();

    if (best_raw_path.empty()) {
        std::printf("FAILED to find path in %.2f s with min_clear=%.2f mm\n", plan_sec, target_clear * 1000.0f);
        return 1;
    }
    std::printf("SOLVED in %.2f s! Raw waypoints: %zu\n", plan_sec, best_raw_path.size());

    // Step 1: Trim path as soon as robust ray-escape (clearance >= 40 mm along a straight line to infinity) holds,
    // plus add 2 clean steps along that escape ray for extra simulator margin!
    size_t trim_idx = best_raw_path.size() - 1;
    Vec3d escape_dir{0, 0, 1};
    float escape_clear = 0.0f;
    for (size_t i = 1; i < best_raw_path.size(); ++i) {
        Vec3d u;
        float rc = 0.0f;
        if (wm.check_ray_escape(best_raw_path[i], 0.035f, &u, &rc)) {
            trim_idx = i;
            escape_dir = u;
            escape_clear = rc;
            break;
        }
    }
    best_raw_path.resize(trim_idx + 1);
    // Add 0.16m push along escape_dir if inside workspace bounds so it's unmistakably separated!
    for (int k = 0; k < 2; ++k) {
        Pose pushed = best_raw_path.back();
        pushed.p = pushed.p + escape_dir * 0.085;
        if (pushed.p.x > -0.70 && pushed.p.x < 3.10 &&
            pushed.p.y > -0.70 && pushed.p.y < 3.10 &&
            pushed.p.z > -0.70 && pushed.p.z < 3.10 &&
            wm.edge_valid(best_raw_path.back(), pushed, target_clear, true)) {
            best_raw_path.push_back(pushed);
        }
    }
    wm.check_ray_escape(best_raw_path.back(), 0.025f, &escape_dir, &escape_clear);
    std::printf("After ray-escape trim: %zu waypoints, final escape_dir=(%.3f, %.3f, %.3f), ray_clear=%.1f mm\n",
                best_raw_path.size(), escape_dir.x, escape_dir.y, escape_dir.z, escape_clear * 1000.0f);

    // Step 2: Continuous shortcutting + clearance maximization!
    std::mt19937 srng(42);
    std::vector<Pose> spath = best_raw_path;
    for (int iter = 0; iter < 600 && spath.size() > 2; ++iter) {
        int i = srng() % (spath.size() - 1);
        int j = i + 2 + (srng() % std::max<int>(1, (int)spath.size() - i - 2));
        if (j >= (int)spath.size()) continue;
        if (wm.edge_valid(spath[i], spath[j], target_clear, true)) {
            spath.erase(spath.begin() + i + 1, spath.begin() + j);
        }
    }
    std::printf("After continuous shortcutting: %zu waypoints\n", spath.size());

    // Densify into legal simulator actions: ||dp|| <= 0.095 m, ||drot|| <= 0.190 rad!
    // Wait: let's also try to increase clearance of intermediate waypoints before action discretization!
    const double MAX_DP = 0.095;
    const double MAX_DA = 0.190;

    auto discretize_to_actions = [&](const std::vector<Pose>& pts) {
        std::vector<Pose> acts;
        acts.push_back(pts[0]);
        for (size_t i = 0; i + 1 < pts.size(); ++i) {
            const Pose& a = pts[i];
            const Pose& b = pts[i + 1];
            double dp = (b.p - a.p).norm();
            double da = quat_angle_dist(a.q, b.q);
            int n = std::max(1, (int)std::ceil(std::max(dp / MAX_DP, da / MAX_DA)));
            for (int k = 1; k <= n; ++k) {
                acts.push_back(pose_interp(a, b, (double)k / n));
            }
        }
        return acts;
    };

    std::vector<Pose> actions = discretize_to_actions(spath);
    std::printf("Initial discretized action count: %zu\n", actions.size() - 1);

    // Push intermediate action waypoints slightly higher in clearance if valid under BOTH velocity laws!
    for (int pass = 0; pass < 4; ++pass) {
        for (size_t i = 1; i + 1 < actions.size(); ++i) {
            float c_cur = wm.clearance_exact(actions[i], -1.0f);
            if (c_cur < 0.025f) {
                Pose cand = actions[i];
                if (wm.retract_pose(cand, std::min(0.028f, c_cur + 0.006f), 3)) {
                    double dp1 = (cand.p - actions[i - 1].p).norm();
                    double da1 = quat_angle_dist(cand.q, actions[i - 1].q);
                    double dp2 = (actions[i + 1].p - cand.p).norm();
                    double da2 = quat_angle_dist(actions[i + 1].q, cand.q);
                    float ec1 = 0, ec2 = 0, orig1 = 0, orig2 = 0;
                    wm.edge_valid(actions[i - 1], actions[i], 0.0f, true, &orig1);
                    wm.edge_valid(actions[i], actions[i + 1], 0.0f, true, &orig2);
                    if (dp1 <= MAX_DP && da1 <= MAX_DA && dp2 <= MAX_DP && da2 <= MAX_DA &&
                        wm.edge_valid(actions[i - 1], cand, target_clear, true, &ec1) &&
                        wm.edge_valid(cand, actions[i + 1], target_clear, true, &ec2) &&
                        std::min(ec1, ec2) > std::min(orig1, orig2)) {
                        actions[i] = cand;
                    }
                }
            }
        }
    }

    // Greedy action-level shortcutting (collapse sequences of poses into fewer legal action steps!)
    bool improved = true;
    while (improved) {
        improved = false;
        for (size_t i = 0; i + 2 < actions.size(); ++i) {
            // Find furthest j reachable in ONE legal action step with clearance >= target_clear + 2mm (or >= existing min)
            for (size_t j = std::min(actions.size() - 1, i + 8); j >= i + 2; --j) {
                double dp = (actions[j].p - actions[i].p).norm();
                double da = quat_angle_dist(actions[j].q, actions[i].q);
                if (dp <= MAX_DP && da <= MAX_DA) {
                    float min_orig = 1e9f;
                    for (size_t k = i; k < j; ++k) {
                        float ec = 0;
                        wm.edge_valid(actions[k], actions[k + 1], -1.0f, true, &ec);
                        if (ec < min_orig) min_orig = ec;
                    }
                    float req = std::min(0.018f, min_orig - 0.001f);
                    req = std::max(req, target_clear);
                    float ec_new = 0;
                    if (wm.edge_valid(actions[i], actions[j], req, true, &ec_new)) {
                        actions.erase(actions.begin() + i + 1, actions.begin() + j);
                        improved = true;
                        break;
                    }
                }
            }
        }
    }

    // Also try 2-step bridges between i and j (replacing 3+ steps with 2 steps!)
    for (int iter = 0; iter < 500 && actions.size() > 4; ++iter) {
        size_t i = srng() % (actions.size() - 3);
        size_t j = std::min(actions.size() - 1, i + 3 + (srng() % 4));
        if (j - i < 3) continue;
        Pose mid = pose_interp(actions[i], actions[j], 0.5);
        double dp1 = (mid.p - actions[i].p).norm();
        double da1 = quat_angle_dist(mid.q, actions[i].q);
        double dp2 = (actions[j].p - mid.p).norm();
        double da2 = quat_angle_dist(actions[j].q, mid.q);
        if (dp1 <= MAX_DP && da1 <= MAX_DA && dp2 <= MAX_DP && da2 <= MAX_DA) {
            float min_orig = 1e9f;
            for (size_t k = i; k < j; ++k) {
                float ec = 0;
                wm.edge_valid(actions[k], actions[k + 1], -1.0f, true, &ec);
                if (ec < min_orig) min_orig = ec;
            }
            float req = std::max(target_clear, std::min(0.018f, min_orig - 0.001f));
            if (wm.edge_valid(actions[i], mid, req, true) && wm.edge_valid(mid, actions[j], req, true)) {
                actions.erase(actions.begin() + i + 1, actions.begin() + j);
                actions.insert(actions.begin() + i + 1, mid);
            }
        }
    }

    // Final verification of EVERY action step under BOTH interpolation laws!
    float global_min_clear = 1e9f;
    int worst_step = -1;
    for (size_t i = 0; i + 1 < actions.size(); ++i) {
        float ec = 0;
        bool ok = wm.edge_valid(actions[i], actions[i + 1], 0.0f, true, &ec);
        if (!ok || ec < global_min_clear) {
            global_min_clear = ec;
            worst_step = (int)i;
        }
    }
    Vec3d final_u;
    float final_rc = 0;
    bool final_esc = wm.check_ray_escape(actions.back(), 0.020f, &final_u, &final_rc);

    std::printf("=== FINAL PLAN SUMMARY ===\n");
    std::printf("Move actions: %zu (+ 1 grab = %zu / 198 total actions)\n", actions.size() - 1, actions.size());
    std::printf("Global minimum clearance (both laws, 225k fine pts): %.2f mm (at step %d)\n",
                global_min_clear * 1000.0f, worst_step);
    std::printf("Final pose ray-escape: %s, dir=(%.3f, %.3f, %.3f), ray_clear=%.2f mm\n",
                final_esc ? "YES" : "NO", final_u.x, final_u.y, final_u.z, final_rc * 1000.0f);

    // Save JSON plan
    FILE* jf = std::fopen("/app/solution_plan.json", "w");
    std::fprintf(jf, "{\n  \"min_clearance_m\": %.6f,\n  \"escape_dir\": [%.6f, %.6f, %.6f],\n  \"waypoints\": [\n",
                 global_min_clear, final_u.x, final_u.y, final_u.z);
    for (size_t i = 0; i < actions.size(); ++i) {
        const auto& wp = actions[i];
        float c = wm.clearance_exact(wp, -1.0f);
        bool esc = wm.check_ray_escape(wp, 0.015f);
        std::fprintf(jf, "    {\"pos\": [%.7f, %.7f, %.7f], \"quat\": [%.7f, %.7f, %.7f, %.7f], \"clear_m\": %.6f, \"ray_escape\": %s}%s\n",
                     wp.p.x, wp.p.y, wp.p.z, wp.q.w, wp.q.x, wp.q.y, wp.q.z, c,
                     esc ? "true" : "false", (i + 1 < actions.size()) ? "," : "");
    }
    std::fprintf(jf, "  ]\n}\n");
    std::fclose(jf);
    std::printf("Saved /app/solution_plan.json!\n");
    return 0;
}

#include <algorithm>
#include <atomic>
#include <chrono>
#include <cmath>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <iostream>
#include <mutex>
#include <numeric>
#include <random>
#include <thread>
#include <unordered_map>
#include <vector>

struct Vec3f { float x, y, z; };

struct Vec3d {
    double x, y, z;
    Vec3d operator+(const Vec3d& o) const { return {x + o.x, y + o.y, z + o.z}; }
    Vec3d operator-(const Vec3d& o) const { return {x - o.x, y - o.y, z - o.z}; }
    Vec3d operator*(double s) const { return {x * s, y * s, z * s}; }
    double dot(const Vec3d& o) const { return x * o.x + y * o.y + z * o.z; }
    Vec3d cross(const Vec3d& o) const {
        return {y * o.z - z * o.y, z * o.x - x * o.z, x * o.y - y * o.x};
    }
    double norm() const { return std::sqrt(x * x + y * y + z * z); }
};

struct Quat {
    double w, x, y, z;
    void normalize() {
        double n = std::sqrt(w * w + x * x + y * y + z * z);
        if (n > 0) { w /= n; x /= n; y /= n; z /= n; }
        if (w < 0) { w = -w; x = -x; y = -y; z = -z; }
    }
    Quat operator*(const Quat& o) const {
        return {
            w * o.w - x * o.x - y * o.y - z * o.z,
            w * o.x + x * o.w + y * o.z - z * o.y,
            w * o.y - x * o.z + y * o.w + z * o.x,
            w * o.z + x * o.y - y * o.x + z * o.w
        };
    }
};

static inline Quat quat_from_rotvec(const Vec3d& rv) {
    double angle = rv.norm();
    if (angle < 1e-12) return {1.0, 0.5 * rv.x, 0.5 * rv.y, 0.5 * rv.z};
    double s = std::sin(0.5 * angle) / angle;
    Quat q{std::cos(0.5 * angle), rv.x * s, rv.y * s, rv.z * s};
    q.normalize();
    return q;
}

static inline Vec3d rotvec_from_quat(Quat q) {
    if (q.w < 0) { q.w = -q.w; q.x = -q.x; q.y = -q.y; q.z = -q.z; }
    double vnorm = std::sqrt(q.x * q.x + q.y * q.y + q.z * q.z);
    if (vnorm < 1e-12) return {2.0 * q.x, 2.0 * q.y, 2.0 * q.z};
    double angle = 2.0 * std::atan2(vnorm, q.w);
    double scale = angle / vnorm;
    return {q.x * scale, q.y * scale, q.z * scale};
}

static inline double quat_angle_dist(const Quat& a, const Quat& b) {
    double d = std::abs(a.w * b.w + a.x * b.x + a.y * b.y + a.z * b.z);
    if (d >= 1.0) return 0.0;
    return 2.0 * std::acos(d);
}

static inline Quat quat_slerp(const Quat& a, Quat b, double t) {
    double dot = a.w * b.w + a.x * b.x + a.y * b.y + a.z * b.z;
    if (dot < 0.0) { dot = -dot; b = {-b.w, -b.x, -b.y, -b.z}; }
    if (dot > 0.9995) {
        Quat r{a.w + t * (b.w - a.w), a.x + t * (b.x - a.x),
               a.y + t * (b.y - a.y), a.z + t * (b.z - a.z)};
        r.normalize();
        return r;
    }
    double theta_0 = std::acos(dot);
    double theta = theta_0 * t;
    double sin_theta = std::sin(theta);
    double sin_theta_0 = std::sin(theta_0);
    double s0 = std::cos(theta) - dot * sin_theta / sin_theta_0;
    double s1 = sin_theta / sin_theta_0;
    Quat r{s0 * a.w + s1 * b.w, s0 * a.x + s1 * b.x,
           s0 * a.y + s1 * b.y, s0 * a.z + s1 * b.z};
    r.normalize();
    return r;
}

struct Pose { Vec3d p; Quat q; };

static inline double pose_dist(const Pose& a, const Pose& b) {
    return (a.p - b.p).norm() + 0.85 * quat_angle_dist(a.q, b.q);
}

static inline Pose pose_interp(const Pose& a, const Pose& b, double t) {
    return {a.p + (b.p - a.p) * t, quat_slerp(a.q, b.q, t)};
}

struct Mat3f {
    float m[9];
    float tx, ty, tz;
    static Mat3f from_pose(const Pose& pose) {
        Mat3f res;
        double w = pose.q.w, x = pose.q.x, y = pose.q.y, z = pose.q.z;
        double xx = x * x, yy = y * y, zz = z * z;
        double xy = x * y, xz = x * z, yz = y * z;
        double wx = w * x, wy = w * y, wz = w * z;
        res.m[0] = (float)(1.0 - 2.0 * (yy + zz));
        res.m[1] = (float)(2.0 * (xy - wz));
        res.m[2] = (float)(2.0 * (xz + wy));
        res.m[3] = (float)(2.0 * (xy + wz));
        res.m[4] = (float)(1.0 - 2.0 * (xx + zz));
        res.m[5] = (float)(2.0 * (yz - wx));
        res.m[6] = (float)(2.0 * (xz - wy));
        res.m[7] = (float)(2.0 * (yz + wx));
        res.m[8] = (float)(1.0 - 2.0 * (xx + yy));
        res.tx = (float)pose.p.x; res.ty = (float)pose.p.y; res.tz = (float)pose.p.z;
        return res;
    }
    inline Vec3f apply(const Vec3f& v) const {
        return {
            m[0] * v.x + m[1] * v.y + m[2] * v.z + tx,
            m[3] * v.x + m[4] * v.y + m[5] * v.z + ty,
            m[6] * v.x + m[7] * v.y + m[8] * v.z + tz
        };
    }
    inline Vec3f rotate_only(const Vec3f& v) const {
        return {
            m[0] * v.x + m[1] * v.y + m[2] * v.z,
            m[3] * v.x + m[4] * v.y + m[5] * v.z,
            m[6] * v.x + m[7] * v.y + m[8] * v.z
        };
    }
};

struct BVHNode {
    Vec3f center;
    float radius;
    int left, right, start, count;
};

struct WorldModel {
    int nx, ny, nz;
    float dx, inv_dx;
    float gmin_x, gmin_y, gmin_z, gmax_x, gmax_y, gmax_z;
    float bmin_x, bmin_y, bmin_z, bmax_x, bmax_y, bmax_z;
    Vec3d pos_b0;

    std::vector<int16_t> sdf_i16;
    std::vector<Vec3f> med_c, b_coarse, b_med, b_fine;
    std::vector<float> med_r;
    float max_local_radius;
    std::vector<BVHNode> bvh_coarse;
    std::vector<BVHNode> bvh_fine;

    void load(const char* path) {
        FILE* f = std::fopen(path, "rb");
        if (!f) { std::perror("fopen"); std::exit(1); }
        int32_t shape[3], counts[4];
        double d_dx, gmin[3], bmin[3], bmax[3], pb0[3];
        if (std::fread(shape, sizeof(int32_t), 3, f) != 3) std::exit(1);
        if (std::fread(&d_dx, sizeof(double), 1, f) != 1) std::exit(1);
        if (std::fread(gmin, sizeof(double), 3, f) != 3) std::exit(1);
        if (std::fread(bmin, sizeof(double), 3, f) != 3) std::exit(1);
        if (std::fread(bmax, sizeof(double), 3, f) != 3) std::exit(1);
        if (std::fread(pb0, sizeof(double), 3, f) != 3) std::exit(1);
        if (std::fread(counts, sizeof(int32_t), 4, f) != 4) std::exit(1);

        nx = shape[0]; ny = shape[1]; nz = shape[2];
        dx = (float)d_dx; inv_dx = 1.0f / dx;
        gmin_x = (float)gmin[0]; gmin_y = (float)gmin[1]; gmin_z = (float)gmin[2];
        gmax_x = gmin_x + (nx - 1.001f) * dx;
        gmax_y = gmin_y + (ny - 1.001f) * dx;
        gmax_z = gmin_z + (nz - 1.001f) * dx;
        bmin_x = (float)bmin[0]; bmin_y = (float)bmin[1]; bmin_z = (float)bmin[2];
        bmax_x = (float)bmax[0]; bmax_y = (float)bmax[1]; bmax_z = (float)bmax[2];
        pos_b0 = {pb0[0], pb0[1], pb0[2]};

        med_c.resize(counts[0]); med_r.resize(counts[0]);
        b_coarse.resize(counts[1]); b_med.resize(counts[2]); b_fine.resize(counts[3]);
        if (std::fread(med_c.data(), sizeof(Vec3f), counts[0], f) != (size_t)counts[0]) std::exit(1);
        if (std::fread(med_r.data(), sizeof(float), counts[0], f) != (size_t)counts[0]) std::exit(1);
        if (std::fread(b_coarse.data(), sizeof(Vec3f), counts[1], f) != (size_t)counts[1]) std::exit(1);
        if (std::fread(b_med.data(), sizeof(Vec3f), counts[2], f) != (size_t)counts[2]) std::exit(1);
        if (std::fread(b_fine.data(), sizeof(Vec3f), counts[3], f) != (size_t)counts[3]) std::exit(1);

        size_t total_vox = (size_t)nx * ny * nz;
        sdf_i16.resize(total_vox);
        if (std::fread(sdf_i16.data(), sizeof(int16_t), total_vox, f) != total_vox) std::exit(1);
        std::fclose(f);

        max_local_radius = 0.0f;
        for (const auto& p : b_fine) {
            float r = std::sqrt(p.x * p.x + p.y * p.y + p.z * p.z);
            if (r > max_local_radius) max_local_radius = r;
        }
        build_bvh(b_coarse, bvh_coarse, 24);
        build_bvh(b_fine, bvh_fine, 48);
        std::printf("Loaded WorldModel: coarse_bvh=%zu, fine_bvh=%zu\n", bvh_coarse.size(), bvh_fine.size());
    }

    int build_bvh(std::vector<Vec3f>& pts, std::vector<BVHNode>& nodes, int leaf_sz, int start = 0, int count = -1) {
        if (count < 0) count = (int)pts.size();
        int idx = (int)nodes.size();
        nodes.push_back({});
        Vec3f mn{1e9f, 1e9f, 1e9f}, mx{-1e9f, -1e9f, -1e9f};
        for (int i = start; i < start + count; ++i) {
            const auto& p = pts[i];
            mn.x = std::min(mn.x, p.x); mn.y = std::min(mn.y, p.y); mn.z = std::min(mn.z, p.z);
            mx.x = std::max(mx.x, p.x); mx.y = std::max(mx.y, p.y); mx.z = std::max(mx.z, p.z);
        }
        Vec3f c{0.5f * (mn.x + mx.x), 0.5f * (mn.y + mx.y), 0.5f * (mn.z + mx.z)};
        float r2 = 0.0f;
        for (int i = start; i < start + count; ++i) {
            float dx_ = pts[i].x - c.x, dy_ = pts[i].y - c.y, dz_ = pts[i].z - c.z;
            r2 = std::max(r2, dx_ * dx_ + dy_ * dy_ + dz_ * dz_);
        }
        nodes[idx] = {c, std::sqrt(r2), -1, -1, start, count};
        if (count <= leaf_sz) return idx;
        float sx = mx.x - mn.x, sy = mx.y - mn.y, sz = mx.z - mn.z;
        int axis = (sx >= sy && sx >= sz) ? 0 : ((sy >= sz) ? 1 : 2);
        int mid = start + count / 2;
        std::nth_element(pts.begin() + start, pts.begin() + mid, pts.begin() + start + count,
                         [axis](const Vec3f& a, const Vec3f& b) {
                             return (axis == 0) ? (a.x < b.x) : ((axis == 1) ? (a.y < b.y) : (a.z < b.z));
                         });
        int l = build_bvh(pts, nodes, leaf_sz, start, mid - start);
        int r = build_bvh(pts, nodes, leaf_sz, mid, start + count - mid);
        nodes[idx].left = l; nodes[idx].right = r;
        return idx;
    }

    inline float query_sdf(const Vec3f& w) const {
        if (w.x <= gmin_x || w.x >= gmax_x ||
            w.y <= gmin_y || w.y >= gmax_y ||
            w.z <= gmin_z || w.z >= gmax_z) {
            float dx_ = std::max(0.0f, std::max(bmin_x - w.x, w.x - bmax_x));
            float dy_ = std::max(0.0f, std::max(bmin_y - w.y, w.y - bmax_y));
            float dz_ = std::max(0.0f, std::max(bmin_z - w.z, w.z - bmax_z));
            return std::sqrt(dx_ * dx_ + dy_ * dy_ + dz_ * dz_);
        }
        float fx = (w.x - gmin_x) * inv_dx;
        float fy = (w.y - gmin_y) * inv_dx;
        float fz = (w.z - gmin_z) * inv_dx;
        int i = (int)fx, j = (int)fy, k = (int)fz;
        float tx = fx - i, ty = fy - j, tz = fz - k;
        size_t s_y = (size_t)nz, s_x = (size_t)ny * nz;
        size_t base = (size_t)i * s_x + (size_t)j * s_y + (size_t)k;
        float c00 = sdf_i16[base] + tx * (sdf_i16[base + s_x] - sdf_i16[base]);
        float c01 = sdf_i16[base + 1] + tx * (sdf_i16[base + s_x + 1] - sdf_i16[base + 1]);
        float c10 = sdf_i16[base + s_y] + tx * (sdf_i16[base + s_x + s_y] - sdf_i16[base + s_y]);
        float c11 = sdf_i16[base + s_y + 1] + tx * (sdf_i16[base + s_x + s_y + 1] - sdf_i16[base + s_y + 1]);
        float c0 = c00 + ty * (c10 - c00);
        float c1 = c01 + ty * (c11 - c01);
        return (c0 + tz * (c1 - c0)) * 0.0001f;
    }

    inline Vec3f query_sdf_grad(const Vec3f& w) const {
        const float eps = 0.005f;
        float gx = query_sdf({w.x + eps, w.y, w.z}) - query_sdf({w.x - eps, w.y, w.z});
        float gy = query_sdf({w.x, w.y + eps, w.z}) - query_sdf({w.x, w.y - eps, w.z});
        float gz = query_sdf({w.x, w.y, w.z + eps}) - query_sdf({w.x, w.y, w.z - eps});
        float n = std::sqrt(gx * gx + gy * gy + gz * gz);
        if (n < 1e-8f) return {0.0f, 0.0f, 1.0f};
        return {gx / n, gy / n, gz / n};
    }

    inline bool in_workspace(const Pose& pose) const {
        return !(pose.p.x < -0.78 || pose.p.x > 3.18 ||
                 pose.p.y < -0.78 || pose.p.y > 3.18 ||
                 pose.p.z < -0.78 || pose.p.z > 3.18);
    }

    float eval_bvh(const Mat3f& T, const std::vector<Vec3f>& pts, const std::vector<BVHNode>& nodes,
                   float stop_below, float max_cap, int* best_pt_idx = nullptr, bool use_med_reject = true) const {
        float d_root = query_sdf(T.apply(nodes[0].center)) - nodes[0].radius - 0.002f;
        if (d_root >= max_cap) return d_root;

        if (use_med_reject) {
            for (size_t i = 0; i < med_c.size(); ++i) {
                float d = query_sdf(T.apply(med_c[i])) - (med_r[i] - 0.002f);
                if (d < stop_below) {
                    if (best_pt_idx) *best_pt_idx = -1 - (int)i;
                    return d;
                }
            }
        }

        float best = max_cap;
        int b_idx = 0;
        int stack[64];
        float stack_lb[64];
        int sp = 0;
        stack[sp] = 0; stack_lb[sp++] = d_root;
        while (sp > 0) {
            --sp;
            if (stack_lb[sp] >= best) continue;
            const BVHNode& node = nodes[stack[sp]];
            if (node.left < 0) {
                int end = node.start + node.count;
                for (int i = node.start; i < end; ++i) {
                    float d = query_sdf(T.apply(pts[i]));
                    if (d < best) {
                        best = d;
                        b_idx = i;
                        if (best < stop_below) {
                            if (best_pt_idx) *best_pt_idx = b_idx;
                            return best;
                        }
                    }
                }
            } else {
                const BVHNode& L = nodes[node.left];
                const BVHNode& R = nodes[node.right];
                float lbL = query_sdf(T.apply(L.center)) - L.radius - 0.0018f;
                float lbR = query_sdf(T.apply(R.center)) - R.radius - 0.0018f;
                if (lbL < lbR) {
                    if (lbR < best) { stack[sp] = node.right; stack_lb[sp++] = lbR; }
                    if (lbL < best) { stack[sp] = node.left;  stack_lb[sp++] = lbL; }
                } else {
                    if (lbL < best) { stack[sp] = node.left;  stack_lb[sp++] = lbL; }
                    if (lbR < best) { stack[sp] = node.right; stack_lb[sp++] = lbR; }
                }
            }
        }
        if (best_pt_idx) *best_pt_idx = b_idx;
        return best;
    }

    // Ultra-fast clearance for search (uses coarse 8k BVH + medial spheres; ~2-3 microseconds!)
    inline float clearance_fast(const Pose& pose, float stop_below, int* idx = nullptr) const {
        if (!in_workspace(pose)) return -1.0f;
        return eval_bvh(Mat3f::from_pose(pose), b_coarse, bvh_coarse, stop_below, 0.35f, idx, true);
    }

    // Exact clearance on all 225k fine points!
    inline float clearance_exact(const Pose& pose, float stop_below, float max_cap = 0.40f, int* idx = nullptr) const {
        if (!in_workspace(pose)) return -1.0f;
        return eval_bvh(Mat3f::from_pose(pose), b_fine, bvh_fine, stop_below, max_cap, idx, true);
    }

    // Super-fast 10-microsecond BVH single-contact retraction!
    bool fast_retract(Pose& pose, float target_clear, int max_iters = 8) const {
        for (int it = 0; it < max_iters; ++it) {
            if (!in_workspace(pose)) return false;
            Mat3f T = Mat3f::from_pose(pose);
            int idx = 0;
            // Find true deepest point (do NOT stop early so we push out the deepest penetration!)
            float d = eval_bvh(T, b_coarse, bvh_coarse, -10.0f, target_clear + 0.002f, &idx, false);
            if (d >= target_clear) return true;
            if (d < -0.055f) return false;

            Vec3f local_pt = (idx >= 0) ? b_coarse[idx] : med_c[-1 - idx];
            Vec3f w = T.apply(local_pt);
            Vec3f g = query_sdf_grad(w);
            Vec3f r = T.rotate_only(local_pt);
            Vec3d gd{g.x, g.y, g.z};
            Vec3d rd{r.x, r.y, r.z};
            Vec3d tau = rd.cross(gd);

            // Rigid-body Jacobian J^T = [gd; tau], step delta = (need / (||gd||^2 + 0.6*||tau||^2)) * [gd; 0.6*tau]
            double need = (target_clear - d) + 0.003;
            double denom = 1.0 + 0.5 * tau.dot(tau);
            double alpha = std::min(0.035, need / denom);
            pose.p = pose.p + gd * alpha;
            if (tau.norm() > 1e-8) {
                pose.q = quat_from_rotvec(tau * (0.5 * alpha)) * pose.q;
                pose.q.normalize();
            }
        }
        return clearance_fast(pose, target_clear) >= target_clear;
    }

    // Exact fine retraction for post-processing clearance maximization!
    bool exact_retract(Pose& pose, float target_clear, int max_iters = 8) const {
        for (int it = 0; it < max_iters; ++it) {
            if (!in_workspace(pose)) return false;
            Mat3f T = Mat3f::from_pose(pose);
            int idx = 0;
            float d = eval_bvh(T, b_fine, bvh_fine, -10.0f, target_clear + 0.001f, &idx, false);
            if (d >= target_clear) return true;
            if (d < -0.04f) return false;
            Vec3f local_pt = (idx >= 0) ? b_fine[idx] : med_c[-1 - idx];
            Vec3f w = T.apply(local_pt);
            Vec3f g = query_sdf_grad(w);
            Vec3f r = T.rotate_only(local_pt);
            Vec3d gd{g.x, g.y, g.z}, rd{r.x, r.y, r.z};
            Vec3d tau = rd.cross(gd);
            double need = (target_clear - d) + 0.002;
            double denom = 1.0 + 0.5 * tau.dot(tau);
            double alpha = std::min(0.020, need / denom);
            pose.p = pose.p + gd * alpha;
            if (tau.norm() > 1e-8) {
                pose.q = quat_from_rotvec(tau * (0.5 * alpha)) * pose.q;
                pose.q.normalize();
            }
        }
        return clearance_exact(pose, target_clear) >= target_clear;
    }

    bool edge_valid_fast(const Pose& a, const Pose& b, float min_clear) const {
        double dp = (b.p - a.p).norm();
        double da = quat_angle_dist(a.q, b.q);
        double tip_travel = dp + max_local_radius * da;
        int n_steps = std::max(1, (int)std::ceil(tip_travel / 0.015)); // 15mm tip steps during fast exploration
        for (int i = 1; i <= n_steps; ++i) {
            double s = (double)i / n_steps;
            if (clearance_fast(pose_interp(a, b, s), min_clear) < min_clear) return false;
        }
        return true;
    }

    bool edge_valid_exact(const Pose& a, const Pose& b, float min_clear, bool both_laws = true, float* min_out = nullptr) const {
        double dp = (b.p - a.p).norm();
        double da = quat_angle_dist(a.q, b.q);
        double tip_travel = dp + max_local_radius * da;
        int n_steps = std::max(2, (int)std::ceil(tip_travel / 0.004));
        float worst = 1e9f;
        for (int i = 1; i <= n_steps; ++i) {
            double s = (double)i / n_steps;
            float c = clearance_exact(pose_interp(a, b, s), min_clear);
            if (c < min_clear) return false;
            worst = std::min(worst, c);
        }
        if (both_laws && dp > 1e-6 && da > 1e-6) {
            double T_lin = dp / 0.1, T_ang = da / 0.1;
            double T_tot = std::max(T_lin, T_ang);
            for (int i = 1; i < n_steps; ++i) {
                double t = (T_tot * i) / n_steps;
                Pose mid{a.p + (b.p - a.p) * std::min(1.0, t / T_lin),
                         quat_slerp(a.q, b.q, std::min(1.0, t / T_ang))};
                float c = clearance_exact(mid, min_clear);
                if (c < min_clear) return false;
                worst = std::min(worst, c);
            }
        }
        if (min_out) *min_out = worst;
        return true;
    }

    bool check_ray_escape(const Pose& pose, float min_ray_clear, Vec3d* best_dir = nullptr, float* best_ray_clear = nullptr) const {
        static std::vector<Vec3d> dirs;
        static std::once_flag flag;
        std::call_once(flag, []() {
            dirs.push_back({0, 0, 1}); dirs.push_back({0, 0, -1});
            dirs.push_back({1, 0, 0}); dirs.push_back({-1, 0, 0});
            dirs.push_back({0, 1, 0}); dirs.push_back({0, -1, 0});
            const int N = 160;
            const double phi = M_PI * (3.0 - std::sqrt(5.0));
            for (int i = 0; i < N; ++i) {
                double y = 1.0 - (i / (double)(N - 1)) * 2.0;
                double r = std::sqrt(std::max(0.0, 1.0 - y * y));
                double th = phi * i;
                dirs.push_back({std::cos(th) * r, y, std::sin(th) * r});
            }
        });

        float c0 = clearance_exact(pose, min_ray_clear);
        if (c0 < min_ray_clear) return false;
        float best_c = -1.0f;
        Vec3d best_u{0, 0, 1};
        for (const auto& u : dirs) {
            float ray_min = c0;
            double tau = 0.0;
            bool ok = true;
            while (tau < 4.5) {
                tau += std::max(0.015, 0.85 * (double)ray_min);
                Pose pt{pose.p + u * tau, pose.q};
                Mat3f T = Mat3f::from_pose(pt);
                float d_root = query_sdf(T.apply(bvh_fine[0].center)) - bvh_fine[0].radius - 0.002f;
                if (d_root > 0.30f && tau > 2.5) break;
                float c = eval_bvh(T, b_fine, bvh_fine, min_ray_clear, 0.35f, nullptr, true);
                if (c < min_ray_clear) { ok = false; break; }
                ray_min = std::min(ray_min, c);
            }
            if (ok) {
                if (!best_dir) return true;
                if (ray_min > best_c) { best_c = ray_min; best_u = u; }
            }
        }
        if (best_c >= min_ray_clear) {
            if (best_dir) *best_dir = best_u;
            if (best_ray_clear) *best_ray_clear = best_c;
            return true;
        }
        return false;
    }
};

struct RRTNode { Pose pose; int parent; };

static inline uint64_t hash_pose_6d(const Pose& p) {
    // 10cm position cells x ~0.28rad rotation-vector cells
    Vec3d rv = rotvec_from_quat(p.q);
    int64_t ix = (int64_t)std::floor((p.p.x + 2.0) / 0.10);
    int64_t iy = (int64_t)std::floor((p.p.y + 2.0) / 0.10);
    int64_t iz = (int64_t)std::floor((p.p.z + 2.0) / 0.10);
    int64_t rx = (int64_t)std::floor((rv.x + 4.0) / 0.28);
    int64_t ry = (int64_t)std::floor((rv.y + 4.0) / 0.28);
    int64_t rz = (int64_t)std::floor((rv.z + 4.0) / 0.28);
    uint64_t h = 1469598103934665603ULL;
    auto mix = [&](int64_t v) { h ^= (uint64_t)(v + 1024); h *= 1099511628211ULL; };
    mix(ix); mix(iy); mix(iz); mix(rx); mix(ry); mix(rz);
    return h;
}

int nearest_node(const std::vector<RRTNode>& tree, const Pose& q) {
    int best = 0;
    double best_d = 1e18;
    for (int i = 0; i < (int)tree.size(); ++i) {
        double d = pose_dist(tree[i].pose, q);
        if (d < best_d) { best_d = d; best = i; }
    }
    return best;
}

int main() {
    WorldModel wm;
    wm.load("/app/planner_data.bin");
    Pose q_start{wm.pos_b0, {1.0, 0.0, 0.0, 0.0}};

    // Search at search_clear = 0.0015 m (1.5 mm) on coarse+medial BVH so narrow passage is wide open!
    const float search_clear = 0.0015f;

    std::atomic<bool> solved{false};
    std::mutex sol_mtx;
    std::vector<Pose> raw_path;

    int n_threads = 8;
    std::printf("Launching %d threads (KPIECE-Frontier + Contact-Sliding BiRRT-Connect, search_clear=%.1fmm)...\n",
                n_threads, search_clear * 1000.0f);
    auto t0 = std::chrono::high_resolution_clock::now();

    auto worker = [&](int tid) {
        std::mt19937 rng(2026 + tid * 13337);
        std::uniform_real_distribution<double> uni(0.0, 1.0);
        std::normal_distribution<double> gauss(0.0, 1.0);

        std::vector<RRTNode> treeA, treeB;
        treeA.reserve(80000); treeB.reserve(40000);
        treeA.push_back({q_start, -1});

        struct Cell { std::vector<int> nodes; };
        std::unordered_map<uint64_t, Cell> cellsA;
        std::vector<uint64_t> cell_keysA;
        auto add_node_A = [&](const Pose& p, int parent) -> int {
            int idx = (int)treeA.size();
            treeA.push_back({p, parent});
            uint64_t h = hash_pose_6d(p);
            auto it = cellsA.find(h);
            if (it == cellsA.end()) {
                cell_keysA.push_back(h);
                cellsA[h].nodes.push_back(idx);
            } else {
                it->second.nodes.push_back(idx);
            }
            return idx;
        };
        cellsA[hash_pose_6d(q_start)].nodes.push_back(0);
        cell_keysA.push_back(hash_pose_6d(q_start));

        // Goal tree B seeded with diverse ray-escaping poses around tube_a!
        std::vector<Pose> goals = {
            {{1.2, 0.36, 1.40}, {1, 0, 0, 0}},
            {{1.9, 0.36, 1.10}, {1, 0, 0, 0}},
            {{0.3, 1.60, 0.90}, {1, 0, 0, 0}},
            {{2.2, 1.20, 0.80}, {1, 0, 0, 0}},
        };
        for (const auto& g : goals) {
            if (wm.clearance_fast(g, 0.04f) >= 0.04f) treeB.push_back({g, -1});
        }

        const double step_sz = 0.065;

        auto connect_tree = [&](std::vector<RRTNode>& tree, bool is_A, int start_node, const Pose& target,
                                int max_steps, bool& reached) -> int {
            reached = false;
            int cur_idx = (start_node >= 0) ? start_node : nearest_node(tree, target);
            int last_added = -1;
            for (int st = 0; st < max_steps; ++st) {
                Pose cur = tree[cur_idx].pose;
                double d = pose_dist(cur, target);
                if (d < 1e-6) { reached = true; return cur_idx; }
                double t = std::min(1.0, step_sz / d);
                Pose next = pose_interp(cur, target, t);
                if (wm.edge_valid_fast(cur, next, search_clear)) {
                    cur_idx = is_A ? add_node_A(next, cur_idx) : ((int)tree.size(), tree.push_back({next, cur_idx}), (int)tree.size() - 1);
                    last_added = cur_idx;
                    if (t >= 1.0 - 1e-9) { reached = true; return cur_idx; }
                } else if (st < 16) {
                    // Contact-sliding step!
                    Pose slid = next;
                    if (wm.fast_retract(slid, search_clear + 0.002f, 6) &&
                        pose_dist(cur, slid) <= step_sz * 1.9 &&
                        pose_dist(slid, target) < d - 0.003 &&
                        wm.edge_valid_fast(cur, slid, search_clear)) {
                        cur_idx = is_A ? add_node_A(slid, cur_idx) : ((int)tree.size(), tree.push_back({slid, cur_idx}), (int)tree.size() - 1);
                        last_added = cur_idx;
                    } else {
                        break;
                    }
                } else {
                    break;
                }
            }
            return last_added;
        };

        for (int iter = 0; iter < 500000 && !solved.load(std::memory_order_relaxed); ++iter) {
            double rmode = uni(rng);
            int addedA = -1;

            if (rmode < 0.65) {
                // KPIECE / EST sparse-cell frontier expansion from treeA!
                // Tournament of 4 random 6D cells: pick the SPARSEST cell!
                uint64_t best_key = cell_keysA[rng() % cell_keysA.size()];
                size_t best_cnt = cellsA[best_key].nodes.size();
                for (int k = 0; k < 4; ++k) {
                    uint64_t ck = cell_keysA[rng() % cell_keysA.size()];
                    size_t cnt = cellsA[ck].nodes.size();
                    if (cnt < best_cnt) { best_cnt = cnt; best_key = ck; }
                }
                const auto& cnodes = cellsA[best_key].nodes;
                int base_idx = cnodes[rng() % cnodes.size()];
                const Pose& base = treeA[base_idx].pose;

                // Pick random direction in SE(3) (mix of short local walk and medium push)
                double scale = (uni(rng) < 0.5) ? 0.18 : 0.45;
                Pose target;
                target.p = {
                    base.p.x + gauss(rng) * scale,
                    base.p.y + gauss(rng) * scale,
                    base.p.z + gauss(rng) * scale
                };
                Vec3d rv{gauss(rng) * scale * 1.3, gauss(rng) * scale * 1.3, gauss(rng) * scale * 1.3};
                target.q = quat_from_rotvec(rv) * base.q;
                target.q.normalize();

                bool r = false;
                addedA = connect_tree(treeA, true, base_idx, target, 10, r);
            } else {
                // Global narrow-passage / BiRRT sample
                Pose q_rand;
                q_rand.p = {-0.6 + uni(rng) * 3.5, -0.6 + uni(rng) * 3.0, -0.6 + uni(rng) * 2.2};
                Quat q{gauss(rng), gauss(rng), gauss(rng), gauss(rng)};
                q.normalize();
                q_rand.q = q;
                float c = wm.clearance_fast(q_rand, search_clear);
                if (c < search_clear) {
                    if (c < -0.05f || !wm.fast_retract(q_rand, search_clear + 0.002f, 6)) continue;
                }
                bool r = false;
                addedA = connect_tree(treeA, true, -1, q_rand, 25, r);
            }

            if (addedA >= 0) {
                const Pose& np = treeA[addedA].pose;
                // Quick check: did treeA just escape the loop?!
                if ((np.p - q_start.p).norm() > 0.65 && wm.clearance_fast(np, 0.030f) >= 0.030f) {
                    if (wm.check_ray_escape(np, 0.025f)) {
                        if (!solved.exchange(true)) {
                            std::lock_guard<std::mutex> lk(sol_mtx);
                            for (int c = addedA; c != -1; c = treeA[c].parent) raw_path.push_back(treeA[c].pose);
                            std::reverse(raw_path.begin(), raw_path.end());
                            std::printf("[Thread %d] SOLVED via direct ray-escape at iter %d! treeA=%zu, cells=%zu, path=%zu\n",
                                        tid, iter, treeA.size(), cell_keysA.size(), raw_path.size());
                        }
                        return;
                    }
                    // Also try connecting treeB to this escaped/near-escaped node!
                    bool rB = false;
                    int idxB = connect_tree(treeB, false, -1, np, 60, rB);
                    if (rB && idxB >= 0) {
                        if (!solved.exchange(true)) {
                            std::lock_guard<std::mutex> lk(sol_mtx);
                            std::vector<Pose> pA, pB;
                            for (int c = addedA; c != -1; c = treeA[c].parent) pA.push_back(treeA[c].pose);
                            std::reverse(pA.begin(), pA.end());
                            for (int c = treeB[idxB].parent; c != -1; c = treeB[c].parent) pB.push_back(treeB[c].pose);
                            pA.insert(pA.end(), pB.begin(), pB.end());
                            raw_path = pA;
                            std::printf("[Thread %d] SOLVED via BiRRT connection at iter %d! treeA=%zu, cells=%zu, path=%zu\n",
                                        tid, iter, treeA.size(), cell_keysA.size(), raw_path.size());
                        }
                        return;
                    }
                }
            }

            if (tid == 0 && iter > 0 && iter % 10000 == 0) {
                double max_disp = 0;
                for (const auto& nd : treeA) max_disp = std::max(max_disp, (nd.pose.p - q_start.p).norm());
                std::printf("[Thread 0] iter=%d, treeA=%zu, 6D_cells=%zu, max_disp=%.3fm\n",
                            iter, treeA.size(), cell_keysA.size(), max_disp);
                std::fflush(stdout);
            }
        }
    };

    std::vector<std::thread> threads;
    for (int t = 0; t < n_threads; ++t) threads.emplace_back(worker, t);
    for (auto& th : threads) th.join();

    double plan_sec = std::chrono::duration<double>(std::chrono::high_resolution_clock::now() - t0).count();
    if (raw_path.empty()) {
        std::printf("FAILED after %.2fs\n", plan_sec);
        return 1;
    }
    std::printf("Path found in %.2f s! Optimizing clearance & action count...\n", plan_sec);

    // Subdivide raw_path finely (every ~0.03m / 0.05rad) and run Elastic-Band Clearance Maximization on EXACT 225k BVH!
    std::vector<Pose> dense;
    dense.push_back(raw_path[0]);
    for (size_t i = 0; i + 1 < raw_path.size(); ++i) {
        double d = pose_dist(raw_path[i], raw_path[i + 1]);
        int n = std::max(1, (int)std::ceil(d / 0.03));
        for (int k = 1; k <= n; ++k) dense.push_back(pose_interp(raw_path[i], raw_path[i + 1], (double)k / n));
    }
    std::printf("Dense waypoints: %zu\n", dense.size());

    // Iteratively retract low-clearance waypoints + Laplacian smooth to center path in the exact middle of the passage!
    for (int pass = 0; pass < 40; ++pass) {
        for (size_t i = 1; i + 1 < dense.size(); ++i) {
            // Smooth toward midpoint of neighbors first
            Pose mid = pose_interp(dense[i - 1], dense[i + 1], 0.5);
            Pose cand = pose_interp(dense[i], mid, 0.35);
            float c_cur = wm.clearance_exact(dense[i], -1.0f, 0.05f);
            float target_c = std::min(0.030f, std::max(0.012f, c_cur + 0.005f));
            if (wm.exact_retract(cand, target_c, 4)) {
                // Accept if neighbors remain reasonably close and exact clearance improved or stayed good
                if (pose_dist(dense[i - 1], cand) < 0.08 && pose_dist(cand, dense[i + 1]) < 0.08) {
                    dense[i] = cand;
                }
            } else {
                // Pure clearance push without smoothing
                Pose push = dense[i];
                if (wm.exact_retract(push, c_cur + 0.003f, 4) &&
                    pose_dist(dense[i - 1], push) < 0.08 && pose_dist(push, dense[i + 1]) < 0.08) {
                    dense[i] = push;
                }
            }
        }
    }

    // Measure exact minimum continuous clearance along `dense`!
    float min_dense_clear = 1e9f;
    for (size_t i = 0; i + 1 < dense.size(); ++i) {
        float ec = 0;
        wm.edge_valid_exact(dense[i], dense[i + 1], -1.0f, false, &ec);
        min_dense_clear = std::min(min_dense_clear, ec);
    }
    std::printf("After clearance maximization, continuous exact bottleneck clearance = %.2f mm!\n",
                min_dense_clear * 1000.0f);

    float safe_floor = std::max(0.002f, min_dense_clear - 0.0015f);

    // Trim at earliest robust ray-escape (ray_clear >= 35mm) + 2 steps along escape ray!
    size_t trim_i = dense.size() - 1;
    Vec3d esc_u{0, 0, 1};
    float esc_rc = 0;
    for (size_t i = 1; i < dense.size(); ++i) {
        Vec3d u; float rc = 0;
        if (wm.check_ray_escape(dense[i], 0.035f, &u, &rc)) {
            trim_i = i; esc_u = u; esc_rc = rc; break;
        }
    }
    dense.resize(trim_i + 1);
    for (int k = 0; k < 2; ++k) {
        Pose pushed = dense.back();
        pushed.p = pushed.p + esc_u * 0.085;
        if (wm.in_workspace(pushed) && wm.edge_valid_exact(dense.back(), pushed, safe_floor, true)) {
            dense.push_back(pushed);
        }
    }

    // Shortcut `dense` using safe_floor!
    std::mt19937 srng(777);
    for (int iter = 0; iter < 1000 && dense.size() > 2; ++iter) {
        size_t i = srng() % (dense.size() - 1);
        size_t j = i + 2 + (srng() % std::max<size_t>(1, dense.size() - i - 2));
        if (j >= dense.size()) continue;
        // Require at least min(0.015, local_min) so we don't sacrifice clearance in wide areas!
        float loc_min = 1e9f;
        for (size_t k = i; k < j; ++k) {
            float ec = 0;
            wm.edge_valid_exact(dense[k], dense[k + 1], -1.0f, false, &ec);
            loc_min = std::min(loc_min, ec);
        }
        float req = std::max(safe_floor, std::min(0.015f, loc_min - 0.001f));
        if (wm.edge_valid_exact(dense[i], dense[j], req, true)) {
            dense.erase(dense.begin() + i + 1, dense.begin() + j);
        }
    }

    // Discretize into legal simulator actions (||dp|| <= 0.095 m, ||da|| <= 0.190 rad)
    const double MAX_DP = 0.095;
    const double MAX_DA = 0.190;
    std::vector<Pose> actions;
    actions.push_back(dense[0]);
    for (size_t i = 0; i + 1 < dense.size(); ++i) {
        double dp = (dense[i + 1].p - dense[i].p).norm();
        double da = quat_angle_dist(dense[i + 1].q, dense[i].q);
        int n = std::max(1, (int)std::ceil(std::max(dp / MAX_DP, da / MAX_DA)));
        for (int k = 1; k <= n; ++k) actions.push_back(pose_interp(dense[i], dense[i + 1], (double)k / n));
    }

    // Greedy action-level collapsing (verifying BOTH velocity laws!)
    bool changed = true;
    while (changed) {
        changed = false;
        for (size_t i = 0; i + 2 < actions.size(); ++i) {
            for (size_t j = std::min(actions.size() - 1, i + 10); j >= i + 2; --j) {
                double dp = (actions[j].p - actions[i].p).norm();
                double da = quat_angle_dist(actions[j].q, actions[i].q);
                if (dp <= MAX_DP && da <= MAX_DA) {
                    float loc_min = 1e9f;
                    for (size_t k = i; k < j; ++k) {
                        float ec = 0;
                        wm.edge_valid_exact(actions[k], actions[k + 1], -1.0f, true, &ec);
                        loc_min = std::min(loc_min, ec);
                    }
                    float req = std::max(safe_floor, std::min(0.015f, loc_min - 0.001f));
                    if (wm.edge_valid_exact(actions[i], actions[j], req, true)) {
                        actions.erase(actions.begin() + i + 1, actions.begin() + j);
                        changed = true;
                        break;
                    }
                }
            }
        }
    }

    float final_min_clear = 1e9f;
    int worst_step = -1;
    for (size_t i = 0; i + 1 < actions.size(); ++i) {
        float ec = 0;
        wm.edge_valid_exact(actions[i], actions[i + 1], -1.0f, true, &ec);
        if (ec < final_min_clear) { final_min_clear = ec; worst_step = (int)i; }
    }
    Vec3d final_u{0, 0, 1};
    float final_rc = 0;
    bool final_esc = wm.check_ray_escape(actions.back(), 0.020f, &final_u, &final_rc);

    std::printf("=== OPTIMIZED SOLUTION PLAN ===\n");
    std::printf("Move actions: %zu (+ 1 grab = %zu / 198)\n", actions.size() - 1, actions.size());
    std::printf("Minimum clearance across all 225k pts & both velocity laws: %.2f mm (step %d)\n",
                final_min_clear * 1000.0f, worst_step);
    std::printf("Final ray-escape: %s, dir=(%.3f, %.3f, %.3f), ray_clear=%.2f mm\n",
                final_esc ? "YES" : "NO", final_u.x, final_u.y, final_u.z, final_rc * 1000.0f);

    FILE* jf = std::fopen("/app/solution_plan.json", "w");
    std::fprintf(jf, "{\n  \"min_clearance_m\": %.6f,\n  \"escape_dir\": [%.6f, %.6f, %.6f],\n  \"waypoints\": [\n",
                 final_min_clear, final_u.x, final_u.y, final_u.z);
    for (size_t i = 0; i < actions.size(); ++i) {
        const auto& wp = actions[i];
        float c = wm.clearance_exact(wp, -1.0f);
        bool esc = wm.check_ray_escape(wp, 0.015f);
        std::fprintf(jf, "    {\"pos\": [%.7f, %.7f, %.7f], \"quat\": [%.7f, %.7f, %.7f, %.7f], \"clear_m\": %.6f, \"ray_escape\": %s}%s\n",
                     wp.p.x, wp.p.y, wp.p.z, wp.q.w, wp.q.x, wp.q.y, wp.q.z, c,
                     esc ? "true" : "false", (i + 1 < actions.size()) ? "," : "");
    }
    std::fprintf(jf, "  ]\n}\n");
    std::fclose(jf);
    return 0;
}

