#include <algorithm>
#include <chrono>
#include <cmath>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <fstream>
#include <iostream>
#include <mutex>
#include <random>
#include <sstream>
#include <string>
#include <vector>

struct Vec3f { float x, y, z; };

struct Vec3d {
    double x, y, z;
    Vec3d operator+(const Vec3d& o) const { return {x + o.x, y + o.y, z + o.z}; }
    Vec3d operator-(const Vec3d& o) const { return {x - o.x, y - o.y, z - o.z}; }
    Vec3d operator*(double s) const { return {x * s, y * s, z * s}; }
    double dot(const Vec3d& o) const { return x * o.x + y * o.y + z * o.z; }
    double norm() const { return std::sqrt(x * x + y * y + z * z); }
};

struct Quat {
    double w, x, y, z;
    void normalize() {
        double n = std::sqrt(w * w + x * x + y * y + z * z);
        if (n > 0) { w /= n; x /= n; y /= n; z /= n; }
        if (w < 0) { w = -w; x = -x; y = -y; z = -z; }
    }
    Quat operator*(const Quat& o) const {
        return {
            w * o.w - x * o.x - y * o.y - z * o.z,
            w * o.x + x * o.w + y * o.z - z * o.y,
            w * o.y - x * o.z + y * o.w + z * o.x,
            w * o.z + x * o.y - y * o.x + z * o.w
        };
    }
};

static inline Quat quat_from_rotvec(const Vec3d& rv) {
    double angle = rv.norm();
    if (angle < 1e-12) return {1.0, 0.5 * rv.x, 0.5 * rv.y, 0.5 * rv.z};
    double s = std::sin(0.5 * angle) / angle;
    Quat q{std::cos(0.5 * angle), rv.x * s, rv.y * s, rv.z * s};
    q.normalize();
    return q;
}

static inline double quat_angle_dist(const Quat& a, const Quat& b) {
    double d = std::abs(a.w * b.w + a.x * b.x + a.y * b.y + a.z * b.z);
    return (d >= 1.0) ? 0.0 : 2.0 * std::acos(d);
}

static inline Quat quat_slerp(const Quat& a, Quat b, double t) {
    double dot = a.w * b.w + a.x * b.x + a.y * b.y + a.z * b.z;
    if (dot < 0.0) { dot = -dot; b = {-b.w, -b.x, -b.y, -b.z}; }
    if (dot > 0.9995) {
        Quat r{a.w + t * (b.w - a.w), a.x + t * (b.x - a.x),
               a.y + t * (b.y - a.y), a.z + t * (b.z - a.z)};
        r.normalize();
        return r;
    }
    double theta_0 = std::acos(dot);
    double theta = theta_0 * t;
    double sin_theta = std::sin(theta);
    double sin_theta_0 = std::sin(theta_0);
    double s0 = std::cos(theta) - dot * sin_theta / sin_theta_0;
    double s1 = sin_theta / sin_theta_0;
    Quat r{s0 * a.w + s1 * b.w, s0 * a.x + s1 * b.x,
           s0 * a.y + s1 * b.y, s0 * a.z + s1 * b.z};
    r.normalize();
    return r;
}

struct Pose { Vec3d p; Quat q; };

static inline double pose_dist(const Pose& a, const Pose& b) {
    return (a.p - b.p).norm() + 0.85 * quat_angle_dist(a.q, b.q);
}

static inline Pose pose_interp(const Pose& a, const Pose& b, double t) {
    return {a.p + (b.p - a.p) * t, quat_slerp(a.q, b.q, t)};
}

struct Mat3f {
    float m[9], tx, ty, tz;
    static Mat3f from_pose(const Pose& pose) {
        Mat3f res;
        double w = pose.q.w, x = pose.q.x, y = pose.q.y, z = pose.q.z;
        double xx = x * x, yy = y * y, zz = z * z;
        double xy = x * y, xz = x * z, yz = y * z;
        double wx = w * x, wy = w * y, wz = w * z;
        res.m[0] = (float)(1.0 - 2.0 * (yy + zz));
        res.m[1] = (float)(2.0 * (xy - wz));
        res.m[2] = (float)(2.0 * (xz + wy));
        res.m[3] = (float)(2.0 * (xy + wz));
        res.m[4] = (float)(1.0 - 2.0 * (xx + zz));
        res.m[5] = (float)(2.0 * (yz - wx));
        res.m[6] = (float)(2.0 * (xz - wy));
        res.m[7] = (float)(2.0 * (yz + wx));
        res.m[8] = (float)(1.0 - 2.0 * (xx + yy));
        res.tx = (float)pose.p.x; res.ty = (float)pose.p.y; res.tz = (float)pose.p.z;
        return res;
    }
    inline Vec3f apply(const Vec3f& v) const {
        return {
            m[0] * v.x + m[1] * v.y + m[2] * v.z + tx,
            m[3] * v.x + m[4] * v.y + m[5] * v.z + ty,
            m[6] * v.x + m[7] * v.y + m[8] * v.z + tz
        };
    }
};

struct BVHNode { Vec3f center; float radius; int left, right, start, count; };

struct WorldModel {
    int nx, ny, nz;
    float dx, inv_dx;
    float gmin_x, gmin_y, gmin_z, gmax_x, gmax_y, gmax_z;
    float bmin_x, bmin_y, bmin_z, bmax_x, bmax_y, bmax_z;
    Vec3d pos_b0;
    std::vector<int16_t> sdf_i16;
    std::vector<Vec3f> med_c, b_coarse, b_med, b_fine;
    std::vector<float> med_r;
    float max_local_radius;
    std::vector<BVHNode> bvh_fine;

    void load(const char* path) {
        FILE* f = std::fopen(path, "rb");
        int32_t shape[3], counts[4];
        double d_dx, gmin[3], bmin[3], bmax[3], pb0[3];
        if (std::fread(shape, sizeof(int32_t), 3, f) != 3) std::exit(1);
        if (std::fread(&d_dx, sizeof(double), 1, f) != 1) std::exit(1);
        if (std::fread(gmin, sizeof(double), 3, f) != 3) std::exit(1);
        if (std::fread(bmin, sizeof(double), 3, f) != 3) std::exit(1);
        if (std::fread(bmax, sizeof(double), 3, f) != 3) std::exit(1);
        if (std::fread(pb0, sizeof(double), 3, f) != 3) std::exit(1);
        if (std::fread(counts, sizeof(int32_t), 4, f) != 4) std::exit(1);
        nx = shape[0]; ny = shape[1]; nz = shape[2];
        dx = (float)d_dx; inv_dx = 1.0f / dx;
        gmin_x = (float)gmin[0]; gmin_y = (float)gmin[1]; gmin_z = (float)gmin[2];
        gmax_x = gmin_x + (nx - 1.001f) * dx;
        gmax_y = gmin_y + (ny - 1.001f) * dx;
        gmax_z = gmin_z + (nz - 1.001f) * dx;
        bmin_x = (float)bmin[0]; bmin_y = (float)bmin[1]; bmin_z = (float)bmin[2];
        bmax_x = (float)bmax[0]; bmax_y = (float)bmax[1]; bmax_z = (float)bmax[2];
        pos_b0 = {pb0[0], pb0[1], pb0[2]};
        med_c.resize(counts[0]); med_r.resize(counts[0]);
        b_coarse.resize(counts[1]); b_med.resize(counts[2]); b_fine.resize(counts[3]);
        if (std::fread(med_c.data(), sizeof(Vec3f), counts[0], f) != (size_t)counts[0]) std::exit(1);
        if (std::fread(med_r.data(), sizeof(float), counts[0], f) != (size_t)counts[0]) std::exit(1);
        if (std::fread(b_coarse.data(), sizeof(Vec3f), counts[1], f) != (size_t)counts[1]) std::exit(1);
        if (std::fread(b_med.data(), sizeof(Vec3f), counts[2], f) != (size_t)counts[2]) std::exit(1);
        if (std::fread(b_fine.data(), sizeof(Vec3f), counts[3], f) != (size_t)counts[3]) std::exit(1);
        size_t total_vox = (size_t)nx * ny * nz;
        sdf_i16.resize(total_vox);
        if (std::fread(sdf_i16.data(), sizeof(int16_t), total_vox, f) != total_vox) std::exit(1);
        std::fclose(f);
        max_local_radius = 0.0f;
        for (const auto& p : b_fine) max_local_radius = std::max(max_local_radius, std::sqrt(p.x*p.x + p.y*p.y + p.z*p.z));
        build_bvh(b_fine, bvh_fine, 48);
    }

    int build_bvh(std::vector<Vec3f>& pts, std::vector<BVHNode>& nodes, int leaf_sz, int start = 0, int count = -1) {
        if (count < 0) count = (int)pts.size();
        int idx = (int)nodes.size();
        nodes.push_back({});
        Vec3f mn{1e9f, 1e9f, 1e9f}, mx{-1e9f, -1e9f, -1e9f};
        for (int i = start; i < start + count; ++i) {
            const auto& p = pts[i];
            mn.x = std::min(mn.x, p.x); mn.y = std::min(mn.y, p.y); mn.z = std::min(mn.z, p.z);
            mx.x = std::max(mx.x, p.x); mx.y = std::max(mx.y, p.y); mx.z = std::max(mx.z, p.z);
        }
        Vec3f c{0.5f * (mn.x + mx.x), 0.5f * (mn.y + mx.y), 0.5f * (mn.z + mx.z)};
        float r2 = 0.0f;
        for (int i = start; i < start + count; ++i) {
            float dx_ = pts[i].x - c.x, dy_ = pts[i].y - c.y, dz_ = pts[i].z - c.z;
            r2 = std::max(r2, dx_ * dx_ + dy_ * dy_ + dz_ * dz_);
        }
        nodes[idx] = {c, std::sqrt(r2), -1, -1, start, count};
        if (count <= leaf_sz) return idx;
        float sx = mx.x - mn.x, sy = mx.y - mn.y, sz = mx.z - mn.z;
        int axis = (sx >= sy && sx >= sz) ? 0 : ((sy >= sz) ? 1 : 2);
        int mid = start + count / 2;
        std::nth_element(pts.begin() + start, pts.begin() + mid, pts.begin() + start + count,
                         [axis](const Vec3f& a, const Vec3f& b) {
                             return (axis == 0) ? (a.x < b.x) : ((axis == 1) ? (a.y < b.y) : (a.z < b.z));
                         });
        int l = build_bvh(pts, nodes, leaf_sz, start, mid - start);
        int r = build_bvh(pts, nodes, leaf_sz, mid, start + count - mid);
        nodes[idx].left = l; nodes[idx].right = r;
        return idx;
    }

    inline float query_sdf(const Vec3f& w) const {
        if (w.x <= gmin_x || w.x >= gmax_x || w.y <= gmin_y || w.y >= gmax_y || w.z <= gmin_z || w.z >= gmax_z) {
            float dx_ = std::max(0.0f, std::max(bmin_x - w.x, w.x - bmax_x));
            float dy_ = std::max(0.0f, std::max(bmin_y - w.y, w.y - bmax_y));
            float dz_ = std::max(0.0f, std::max(bmin_z - w.z, w.z - bmax_z));
            return std::sqrt(dx_ * dx_ + dy_ * dy_ + dz_ * dz_);
        }
        float fx = (w.x - gmin_x) * inv_dx, fy = (w.y - gmin_y) * inv_dx, fz = (w.z - gmin_z) * inv_dx;
        int i = (int)fx, j = (int)fy, k = (int)fz;
        float tx = fx - i, ty = fy - j, tz = fz - k;
        size_t s_y = (size_t)nz, s_x = (size_t)ny * nz;
        size_t base = (size_t)i * s_x + (size_t)j * s_y + (size_t)k;
        float c00 = sdf_i16[base] + tx * (sdf_i16[base + s_x] - sdf_i16[base]);
        float c01 = sdf_i16[base + 1] + tx * (sdf_i16[base + s_x + 1] - sdf_i16[base + 1]);
        float c10 = sdf_i16[base + s_y] + tx * (sdf_i16[base + s_x + s_y] - sdf_i16[base + s_y]);
        float c11 = sdf_i16[base + s_y + 1] + tx * (sdf_i16[base + s_x + s_y + 1] - sdf_i16[base + s_y + 1]);
        float c0 = c00 + ty * (c10 - c00);
        float c1 = c01 + ty * (c11 - c01);
        return (c0 + tz * (c1 - c0)) * 0.0001f;
    }

    inline bool in_workspace(const Pose& pose) const {
        return !(pose.p.x < -0.75 || pose.p.x > 3.15 ||
                 pose.p.y < -0.75 || pose.p.y > 3.15 ||
                 pose.p.z < -0.75 || pose.p.z > 3.15);
    }

    float eval_bvh_fine(const Mat3f& T, float stop_below, float max_cap = 0.30f) const {
        float d_root = query_sdf(T.apply(bvh_fine[0].center)) - bvh_fine[0].radius - 0.002f;
        if (d_root >= max_cap) return d_root;
        for (size_t i = 0; i < med_c.size(); ++i) {
            float d = query_sdf(T.apply(med_c[i])) - (med_r[i] - 0.002f);
            if (d < stop_below) return d;
        }
        float best = max_cap;
        int stack[64]; float stack_lb[64]; int sp = 0;
        stack[sp] = 0; stack_lb[sp++] = d_root;
        while (sp > 0) {
            --sp;
            if (stack_lb[sp] >= best) continue;
            const BVHNode& node = bvh_fine[stack[sp]];
            if (node.left < 0) {
                int end = node.start + node.count;
                for (int i = node.start; i < end; ++i) {
                    float d = query_sdf(T.apply(b_fine[i]));
                    if (d < best) { best = d; if (best < stop_below) return best; }
                }
            } else {
                const BVHNode& L = bvh_fine[node.left];
                const BVHNode& R = bvh_fine[node.right];
                float lbL = query_sdf(T.apply(L.center)) - L.radius - 0.0018f;
                float lbR = query_sdf(T.apply(R.center)) - R.radius - 0.0018f;
                if (lbL < lbR) {
                    if (lbR < best) { stack[sp] = node.right; stack_lb[sp++] = lbR; }
                    if (lbL < best) { stack[sp] = node.left;  stack_lb[sp++] = lbL; }
                } else {
                    if (lbL < best) { stack[sp] = node.left;  stack_lb[sp++] = lbL; }
                    if (lbR < best) { stack[sp] = node.right; stack_lb[sp++] = lbR; }
                }
            }
        }
        return best;
    }

    inline float clearance_exact(const Pose& pose, float stop_below, float max_cap = 0.30f) const {
        if (!in_workspace(pose)) return -1.0f;
        return eval_bvh_fine(Mat3f::from_pose(pose), stop_below, max_cap);
    }

    bool edge_clear(const Pose& a, const Pose& b, float min_clear, bool both_laws, float& min_out, double step_res = 0.004) const {
        double dp = (b.p - a.p).norm();
        double da = quat_angle_dist(a.q, b.q);
        double tip_travel = dp + max_local_radius * da;
        int n_steps = std::max(2, (int)std::ceil(tip_travel / step_res));
        float worst = 1e9f;
        for (int i = 0; i <= n_steps; ++i) {
            double s = (double)i / n_steps;
            float c = clearance_exact(pose_interp(a, b, s), min_clear);
            if (c < min_clear) return false;
            worst = std::min(worst, c);
        }
        if (both_laws && dp > 1e-6 && da > 1e-6) {
            double T_lin = dp / 0.1, T_ang = da / 0.1;
            double T_tot = std::max(T_lin, T_ang);
            for (int i = 1; i < n_steps; ++i) {
                double t = (T_tot * i) / n_steps;
                Pose mid{a.p + (b.p - a.p) * std::min(1.0, t / T_lin),
                         quat_slerp(a.q, b.q, std::min(1.0, t / T_ang))};
                float c = clearance_exact(mid, min_clear);
                if (c < min_clear) return false;
                worst = std::min(worst, c);
            }
        }
        min_out = worst;
        return true;
    }

    bool check_ray_escape(const Pose& pose, float min_ray_clear, Vec3d* best_dir = nullptr, float* best_ray_clear = nullptr) const {
        static std::vector<Vec3d> dirs;
        static std::once_flag flag;
        std::call_once(flag, []() {
            dirs.push_back({0, 0, 1}); dirs.push_back({0, 0, -1});
            dirs.push_back({1, 0, 0}); dirs.push_back({-1, 0, 0});
            dirs.push_back({0, 1, 0}); dirs.push_back({0, -1, 0});
            const int N = 240;
            const double phi = M_PI * (3.0 - std::sqrt(5.0));
            for (int i = 0; i < N; ++i) {
                double y = 1.0 - (i / (double)(N - 1)) * 2.0;
                double r = std::sqrt(std::max(0.0, 1.0 - y * y));
                double th = phi * i;
                dirs.push_back({std::cos(th) * r, y, std::sin(th) * r});
            }
        });

        float c0 = clearance_exact(pose, min_ray_clear);
        if (c0 < min_ray_clear) return false;
        float best_c = -1.0f;
        Vec3d best_u{0, 0, 1};
        for (const auto& u : dirs) {
            float ray_min = c0;
            double tau = 0.0;
            bool ok = true;
            while (tau < 4.5) {
                tau += std::max(0.012, 0.85 * (double)ray_min);
                Pose pt{pose.p + u * tau, pose.q};
                Mat3f T = Mat3f::from_pose(pt);
                float d_root = query_sdf(T.apply(bvh_fine[0].center)) - bvh_fine[0].radius - 0.002f;
                if (d_root > 0.30f && tau > 2.5) break;
                float c = eval_bvh_fine(T, min_ray_clear, 0.35f);
                if (c < min_ray_clear) { ok = false; break; }
                ray_min = std::min(ray_min, c);
            }
            if (ok) {
                if (!best_dir) return true;
                if (ray_min > best_c) { best_c = ray_min; best_u = u; }
            }
        }
        if (best_c >= min_ray_clear) {
            if (best_dir) *best_dir = best_u;
            if (best_ray_clear) *best_ray_clear = best_c;
            return true;
        }
        return false;
    }
};

std::vector<Pose> load_plan_json(const char* path) {
    std::ifstream ifs(path);
    std::string line;
    std::vector<Pose> res;
    while (std::getline(ifs, line)) {
        auto p_pos = line.find("\"pos\": [");
        if (p_pos == std::string::npos) continue;
        Pose wp;
        const char* s = line.c_str() + p_pos;
        if (std::sscanf(s, "\"pos\": [%lf, %lf, %lf], \"quat\": [%lf, %lf, %lf, %lf]",
                        &wp.p.x, &wp.p.y, &wp.p.z, &wp.q.w, &wp.q.x, &wp.q.y, &wp.q.z) == 7) {
            wp.q.normalize();
            res.push_back(wp);
        }
    }
    return res;
}

int main() {
    WorldModel wm;
    wm.load("/app/planner_data.bin");
    auto init_wps = load_plan_json("/app/solution_plan.json");
    std::printf("Loaded %zu initial waypoints\n", init_wps.size());

    // Resample evenly at step ~0.04 in SE(3)
    auto resample = [](const std::vector<Pose>& src, double ds) {
        std::vector<Pose> out;
        out.push_back(src[0]);
        for (size_t i = 0; i + 1 < src.size(); ++i) {
            double d = pose_dist(src[i], src[i + 1]);
            int n = std::max(1, (int)std::ceil(d / ds));
            for (int k = 1; k <= n; ++k) out.push_back(pose_interp(src[i], src[i + 1], (double)k / n));
        }
        return out;
    };

    std::vector<Pose> path = resample(init_wps, 0.035);
    std::printf("Resampled to %zu waypoints for Chebyshev max-min clearance optimization...\n", path.size());

    std::mt19937 rng(12345);
    std::normal_distribution<double> gauss(0.0, 1.0);

    double scales_p[] = {0.015, 0.008, 0.004, 0.002, 0.001};
    double scales_q[] = {0.025, 0.014, 0.007, 0.0035, 0.0015};

    for (int stage = 0; stage < 5; ++stage) {
        double sp = scales_p[stage], sq = scales_q[stage];
        for (int pass = 0; pass < 18; ++pass) {
            for (size_t i = 1; i + 1 < path.size(); ++i) {
                float c1 = 0, c2 = 0;
                wm.edge_clear(path[i - 1], path[i], -1.0f, false, c1, 0.008);
                wm.edge_clear(path[i], path[i + 1], -1.0f, false, c2, 0.008);
                float cur_min = std::min(c1, c2);

                // First try pulling slightly toward geodesic midpoint if clearance stays high (>= 25mm or > cur_min)
                Pose mid = pose_interp(path[i - 1], path[i + 1], 0.5);
                Pose smooth_cand = pose_interp(path[i], mid, 0.25);
                float sc1 = 0, sc2 = 0;
                float req_smooth = std::min(0.025f, cur_min);
                if (wm.edge_clear(path[i - 1], smooth_cand, req_smooth, false, sc1, 0.008) &&
                    wm.edge_clear(smooth_cand, path[i + 1], req_smooth, false, sc2, 0.008)) {
                    path[i] = smooth_cand;
                    cur_min = std::min(sc1, sc2);
                }

                // If cur_min < 28mm, run Chebyshev hill-climbing!
                if (cur_min < 0.028f) {
                    for (int trial = 0; trial < 12; ++trial) {
                        Pose cand;
                        cand.p = {path[i].p.x + gauss(rng) * sp,
                                  path[i].p.y + gauss(rng) * sp,
                                  path[i].p.z + gauss(rng) * sp};
                        Vec3d rv{gauss(rng) * sq, gauss(rng) * sq, gauss(rng) * sq};
                        cand.q = quat_from_rotvec(rv) * path[i].q;
                        cand.q.normalize();
                        if (pose_dist(path[i - 1], cand) > 0.12 || pose_dist(cand, path[i + 1]) > 0.12) continue;
                        float nc1 = 0, nc2 = 0;
                        if (wm.edge_clear(path[i - 1], cand, cur_min + 0.00005f, false, nc1, 0.008) &&
                            wm.edge_clear(cand, path[i + 1], cur_min + 0.00005f, false, nc2, 0.008)) {
                            path[i] = cand;
                            cur_min = std::min(nc1, nc2);
                        }
                    }
                }
            }
        }
        float bottleneck = 1e9f;
        for (size_t i = 0; i + 1 < path.size(); ++i) {
            float ec = 0;
            wm.edge_clear(path[i], path[i + 1], -1.0f, false, ec, 0.004);
            bottleneck = std::min(bottleneck, ec);
        }
        std::printf("Stage %d (sp=%.1fmm): continuous bottleneck clearance = %.3f mm\n",
                    stage, sp * 1000.0, bottleneck * 1000.0f);
    }

    // Trim at earliest pose where ray-escape holds with >= 25 mm ray clearance, then add ONE 8cm step along escape ray!
    size_t esc_idx = path.size() - 1;
    Vec3d esc_u{0, 0, 1};
    float esc_rc = 0;
    for (size_t i = 1; i < path.size(); ++i) {
        Vec3d u; float rc = 0;
        if (wm.check_ray_escape(path[i], 0.025f, &u, &rc)) {
            esc_idx = i; esc_u = u; esc_rc = rc; break;
        }
    }
    path.resize(esc_idx + 1);
    Pose extra = path.back();
    extra.p = extra.p + esc_u * 0.085;
    float dummy_ec = 0;
    if (wm.in_workspace(extra) && wm.edge_clear(path.back(), extra, 0.020f, true, dummy_ec, 0.004)) {
        path.push_back(extra);
    }
    std::printf("Trimmed at ray-escape index %zu (+1 insurance step), ray_clear=%.2f mm along (%.3f, %.3f, %.3f)\n",
                esc_idx, esc_rc * 1000.0f, esc_u.x, esc_u.y, esc_u.z);

    // Resample finely (every ~0.015 in SE(3)) for Global Shortest-Path DAG Dynamic Programming!
    std::vector<Pose> dag_pts = resample(path, 0.015);
    size_t N = dag_pts.size();
    std::printf("Running Global DAG Shortest-Path DP on %zu dense curve nodes...\n", N);

    // Compute bottleneck along dag_pts
    float curve_min_clear = 1e9f;
    for (size_t i = 0; i + 1 < N; ++i) {
        float ec = 0;
        wm.edge_clear(dag_pts[i], dag_pts[i + 1], -1.0f, true, ec, 0.003);
        curve_min_clear = std::min(curve_min_clear, ec);
    }
    std::printf("Dense curve exact min clearance (both laws, 3mm step): %.3f mm\n", curve_min_clear * 1000.0f);

    // Try high clearance floor first (e.g. min(12mm, curve_min_clear - 0.8mm))!
    float dp_floor = std::max(0.004f, curve_min_clear - 0.0008f);
    const double MAX_DP = 0.095;
    const double MAX_DA = 0.190;

    std::vector<int> dist(N, 1000000);
    std::vector<float> best_min_c(N, -1.0f);
    std::vector<int> parent(N, -1);
    dist[0] = 0;
    best_min_c[0] = 1.0f;

    for (size_t i = 0; i < N; ++i) {
        if (dist[i] >= 1000000) continue;
        for (size_t j = i + 1; j < N; ++j) {
            double dp = (dag_pts[j].p - dag_pts[i].p).norm();
            double da = quat_angle_dist(dag_pts[i].q, dag_pts[j].q);
            if (dp > MAX_DP || da > MAX_DA) {
                // Note: curve might bend slightly so keep checking a few more j, break if way past
                if (dp > MAX_DP * 1.4 || da > MAX_DA * 1.4) break;
                continue;
            }
            if (dist[i] + 1 > dist[j]) continue;
            // Require higher clearance in wide regions (at least min(15mm, dp_floor_local)), and >= dp_floor everywhere!
            float req = dp_floor;
            float ec = 0;
            if (!wm.edge_clear(dag_pts[i], dag_pts[j], req, true, ec, 0.003)) continue;
            // Also prefer edges that don't unnecessarily skim below 14mm when original curve was > 18mm
            float path_mc = std::min(best_min_c[i], ec);
            if (dist[i] + 1 < dist[j] || (dist[i] + 1 == dist[j] && path_mc > best_min_c[j])) {
                dist[j] = dist[i] + 1;
                best_min_c[j] = path_mc;
                parent[j] = (int)i;
            }
        }
    }

    std::vector<Pose> opt_actions;
    for (int cur = (int)N - 1; cur != -1; cur = parent[cur]) opt_actions.push_back(dag_pts[cur]);
    std::reverse(opt_actions.begin(), opt_actions.end());

    // Also do 10 passes of Chebyshev hill-climbing directly on `opt_actions` under BOTH velocity laws!
    for (int stage = 0; stage < 3; ++stage) {
        double sp = 0.005 * std::pow(0.4, stage);
        double sq = 0.008 * std::pow(0.4, stage);
        for (int pass = 0; pass < 20; ++pass) {
            for (size_t i = 1; i + 1 < opt_actions.size(); ++i) {
                float c1 = 0, c2 = 0;
                wm.edge_clear(opt_actions[i - 1], opt_actions[i], -1.0f, true, c1, 0.003);
                wm.edge_clear(opt_actions[i], opt_actions[i + 1], -1.0f, true, c2, 0.003);
                float cur_min = std::min(c1, c2);
                if (cur_min >= 0.030f) continue;
                for (int tr = 0; tr < 15; ++tr) {
                    Pose cand;
                    cand.p = {opt_actions[i].p.x + gauss(rng) * sp,
                              opt_actions[i].p.y + gauss(rng) * sp,
                              opt_actions[i].p.z + gauss(rng) * sp};
                    Vec3d rv{gauss(rng) * sq, gauss(rng) * sq, gauss(rng) * sq};
                    cand.q = quat_from_rotvec(rv) * opt_actions[i].q;
                    cand.q.normalize();
                    if ((cand.p - opt_actions[i - 1].p).norm() > MAX_DP ||
                        quat_angle_dist(opt_actions[i - 1].q, cand.q) > MAX_DA ||
                        (opt_actions[i + 1].p - cand.p).norm() > MAX_DP ||
                        quat_angle_dist(cand.q, opt_actions[i + 1].q) > MAX_DA) continue;
                    float nc1 = 0, nc2 = 0;
                    if (wm.edge_clear(opt_actions[i - 1], cand, cur_min + 0.00005f, true, nc1, 0.003) &&
                        wm.edge_clear(cand, opt_actions[i + 1], cur_min + 0.00005f, true, nc2, 0.003)) {
                        opt_actions[i] = cand;
                        cur_min = std::min(nc1, nc2);
                    }
                }
            }
        }
    }

    float global_min_c = 1e9f;
    int worst_step = -1;
    for (size_t i = 0; i + 1 < opt_actions.size(); ++i) {
        float ec = 0;
        wm.edge_clear(opt_actions[i], opt_actions[i + 1], -1.0f, true, ec, 0.0025);
        if (ec < global_min_c) { global_min_c = ec; worst_step = (int)i; }
    }
    Vec3d final_u{0, 0, 1}; float final_rc = 0;
    bool final_esc = wm.check_ray_escape(opt_actions.back(), 0.020f, &final_u, &final_rc);

    std::printf("\n=== GLOBALLY OPTIMIZED ACTION PLAN ===\n");
    std::printf("Move actions: %zu (+ 1 grab = %zu / 198 -> projected score = %.4f)\n",
                opt_actions.size() - 1, opt_actions.size(), 1.0 - 0.5 * (opt_actions.size() / 198.0));
    std::printf("Global minimum clearance (both laws, 2.5mm substeps, 225k pts): %.3f mm (at step %d)\n",
                global_min_c * 1000.0f, worst_step);
    std::printf("Final pose ray-escape: %s, dir=(%.3f, %.3f, %.3f), ray_clear=%.2f mm\n",
                final_esc ? "YES" : "NO", final_u.x, final_u.y, final_u.z, final_rc * 1000.0f);

    FILE* jf = std::fopen("/app/optimized_plan.json", "w");
    std::fprintf(jf, "{\n  \"min_clearance_m\": %.6f,\n  \"escape_dir\": [%.6f, %.6f, %.6f],\n  \"waypoints\": [\n",
                 global_min_c, final_u.x, final_u.y, final_u.z);
    for (size_t i = 0; i < opt_actions.size(); ++i) {
        const auto& wp = opt_actions[i];
        float c = wm.clearance_exact(wp, -1.0f);
        bool esc = wm.check_ray_escape(wp, 0.015f);
        std::fprintf(jf, "    {\"pos\": [%.7f, %.7f, %.7f], \"quat\": [%.7f, %.7f, %.7f, %.7f], \"clear_m\": %.6f, \"ray_escape\": %s}%s\n",
                     wp.p.x, wp.p.y, wp.p.z, wp.q.w, wp.q.x, wp.q.y, wp.q.z, c,
                     esc ? "true" : "false", (i + 1 < opt_actions.size()) ? "," : "");
    }
    std::fprintf(jf, "  ]\n}\n");
    std::fclose(jf);
    return 0;
}

